// Game data: crops, buildable modules, upgrades, clients, contracts, milestones.

export const CROPS = {
  lettuce:    { name: 'Lettuce',    icon: '🥬', seedCost: 8,  sell: 22, growTime: 65,  yield: 1, color: 0x86efac, dark: 0x16a34a, shape: 'leafy' },
  kale:       { name: 'Kale',       icon: '🥦', seedCost: 15, sell: 40, growTime: 90,  yield: 1, color: 0x4ade80, dark: 0x166534, shape: 'leafy' },
  basil:      { name: 'Basil',      icon: '🌿', seedCost: 12, sell: 32, growTime: 82,  yield: 1, color: 0x22c55e, dark: 0x15803d, shape: 'bush'  },
  tomato:     { name: 'Tomato',     icon: '🍅', seedCost: 20, sell: 55, growTime: 120, yield: 1, color: 0x4ade80, dark: 0x166534, shape: 'fruit', fruit: 0xef4444 },
  strawberry: { name: 'Strawberry', icon: '🍓', seedCost: 30, sell: 85, growTime: 145, yield: 1, color: 0x86efac, dark: 0x16a34a, shape: 'fruit', fruit: 0xf43f5e },
};
export const CROP_IDS = Object.keys(CROPS);

/* Buildable modules. w×h in grid tiles (tile = 1.6 world units). */
export const MODULES = {
  growrack: { name: 'NFT Grow Rack',  icon: '🌿', w: 2, h: 1, cost: 120, kind: 'grow',    plants: 8,  yield: 6, growth: 1.00, desc: '2×1 · 8 plants · reliable starter' },
  raft:     { name: 'Raft Bed',       icon: '🌊', w: 2, h: 2, cost: 260, kind: 'grow',    plants: 12, yield: 8, growth: 1.10, desc: '2×2 · 12 plants · +10% growth' },
  tower:    { name: 'Vertical Tower', icon: '🗼', w: 1, h: 1, cost: 190, kind: 'grow',    plants: 6,  yield: 5, growth: 1.18, desc: '1×1 · 6 plants · +18% growth' },
  tank:     { name: 'Water Tank',     icon: '💧', w: 1, h: 1, cost: 90,  kind: 'utility', desc: 'Refill all racks at once' },
  bench:    { name: 'Mixing Bench',   icon: '🧪', w: 1, h: 1, cost: 70,  kind: 'utility', desc: 'Mix nutrient batches on site' },
  lamp:     { name: 'LED Sun Lamp',   icon: '💡', w: 1, h: 1, cost: 130, kind: 'boost',   desc: '+10% growth to racks within 2 tiles' },
  planter:  { name: 'Potted Palm',    icon: '🌴', w: 1, h: 1, cost: 45,  kind: 'decor',   desc: 'Sandbox decoration' },
  crate:    { name: 'Produce Crate',  icon: '📦', w: 1, h: 1, cost: 30,  kind: 'decor',   desc: 'Sandbox decoration' },
  sign:     { name: 'Farm Sign',      icon: '🪧', w: 1, h: 1, cost: 80,  kind: 'decor',   desc: 'Sandbox decoration' },
};
export const MODULE_IDS = Object.keys(MODULES);

export const CLIENTS = [
  "Bella's Bistro", 'Verde Cocina', 'The Daily Salad', 'Mercado Sano',
  'Green Fork Café', 'Casa Verde Catering', 'La Huerta Kitchen', 'Fresh Roots Deli',
];

export const MILESTONES = [
  { worth: 2000,  name: 'Greenhouse Graduate', reward: 150 },
  { worth: 5000,  name: 'Hydro Hero',          reward: 400 },
  { worth: 10000, name: 'Farm Magnate',        reward: 800 },
  { worth: 25000, name: 'HYDRO TYCOON',        reward: 2000 },
];

export const UPGRADES = [
  { id: 'led1',     name: 'LED Spectrum Lv.1',     icon: '💡', cost: 400,  desc: '+25% crop growth on every module' },
  { id: 'led2',     name: 'LED Spectrum Lv.2',     icon: '🔆', cost: 900,  desc: '+50% crop growth (replaces Lv.1)', needs: 'led1' },
  { id: 'autoWater', name: 'Auto-Watering',        icon: '🚿', cost: 550,  desc: 'Auto-refills water on all modules' },
  { id: 'autoDose', name: 'Auto-Nutrient Doser',   icon: '🤖', cost: 750,  desc: 'Nutrients slowly auto-dose to 60' },
  { id: 'contracts', name: 'Contract Magnet',      icon: '📋', cost: 700,  desc: '+20% payout on restaurant contracts' },
  { id: 'market',   name: 'Premium Market Deal',   icon: '🤝', cost: 800,  desc: '+15% on all produce sales' },
  { id: 'solar',    name: 'Solar Panel Array',     icon: '☀️', cost: 1500, desc: 'Operating costs halved ($45 → $22/day)' },
];

export function rollPrices() {
  const prices = {};
  for (const id of CROP_IDS) {
    prices[id] = Math.round(CROPS[id].sell * (0.78 + Math.random() * 0.54));
  }
  return prices;
}

export function rollContractOffers(day) {
  const offers = [];
  const used = new Set();
  for (let i = 0; i < 3; i++) {
    let crop = CROP_IDS[Math.floor(Math.random() * CROP_IDS.length)];
    if (used.has(crop)) crop = CROP_IDS[(CROP_IDS.indexOf(crop) + 1 + i) % CROP_IDS.length];
    used.add(crop);
    const qty = 3 + Math.floor(Math.random() * 5) + Math.floor(day / 4);
    const reward = Math.round(CROPS[crop].sell * qty * (1.45 + Math.random() * 0.35));
    const client = CLIENTS[Math.floor(Math.random() * CLIENTS.length)];
    offers.push({
      id: `c${day}-${i}-${Math.random().toString(36).slice(2, 7)}`,
      client, crop, qty, reward,
      deadline: day + 2 + Math.floor(Math.random() * 3),
    });
  }
  return offers;
}

export function netWorth(state, modules = []) {
  let w = state.cash;
  for (const id of CROP_IDS) {
    w += state.produce[id] * state.prices[id];
    w += state.seeds[id] * CROPS[id].seedCost;
  }
  w += state.nutrient * 12 + state.pesticide * 18;
  for (const m of modules) {
    const def = MODULES[m.type];
    if (!def) continue;
    w += Math.round(def.cost * 0.6);
    if (m.data.crop) {
      w += Math.round((m.data.growth / 100) * CROPS[m.data.crop].sell * def.yield * 0.55);
    }
  }
  return Math.round(w);
}

// Isometric world: mobile greenhouse sandbox. Grid, module models, props, lighting.
import * as THREE from 'three';

export const TILE = 1.6;
export const COLS = 15;
export const ROWS = 10;
export const FLOOR_W = COLS * TILE;   // 24
export const FLOOR_D = ROWS * TILE;   // 16

const HALF_W = FLOOR_W / 2, HALF_D = FLOOR_D / 2;

/* tile (col,row) → world center of that single tile */
export function tileCenter(col, row) {
  return { x: -HALF_W + (col + 0.5) * TILE, z: -HALF_D + (row + 0.5) * TILE };
}
/* module anchor (col,row top-left tile) + footprint → world center */
export function moduleCenter(col, row, w, h) {
  return { x: -HALF_W + (col + w / 2) * TILE, z: -HALF_D + (row + h / 2) * TILE };
}
export function worldToTile(x, z) {
  return { col: Math.floor((x + HALF_W) / TILE), row: Math.floor((z + HALF_D) / TILE) };
}

/* ── textures ─────────────────────────────────────────── */
function canvasTex(w, h, draw) {
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  draw(c.getContext('2d'), w, h);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}
function grassTexture() {
  const t = canvasTex(256, 256, (g, w, h) => {
    g.fillStyle = '#4c8a4f'; g.fillRect(0, 0, w, h);
    for (let i = 0; i < 5000; i++) {
      const c = ['#3f7a43', '#58995a', '#457f47', '#63a563'][i % 4];
      g.fillStyle = c; g.globalAlpha = 0.5;
      g.fillRect(Math.random() * w, Math.random() * h, 2, 2 + Math.random() * 2);
    }
    g.globalAlpha = 1;
  });
  t.wrapS = t.wrapT = THREE.RepeatWrapping; t.repeat.set(30, 30);
  return t;
}
function concreteTexture() {
  const t = canvasTex(256, 256, (g, w, h) => {
    g.fillStyle = '#a9b3ad'; g.fillRect(0, 0, w, h);
    for (let i = 0; i < 2300; i++) {
      g.fillStyle = `rgba(${Math.random() < 0.5 ? '255,255,255' : '30,50,40'},${Math.random() * 0.07})`;
      g.fillRect(Math.random() * w, Math.random() * h, 2, 2);
    }
  });
  t.wrapS = t.wrapT = THREE.RepeatWrapping; t.repeat.set(8, 5.5);
  return t;
}
function pavingTexture() {
  const t = canvasTex(256, 256, (g, w, h) => {
    g.fillStyle = '#cbc2ae'; g.fillRect(0, 0, w, h);
    g.strokeStyle = 'rgba(80,70,50,0.25)'; g.lineWidth = 3;
    for (let i = 0; i <= 4; i++) {
      g.beginPath(); g.moveTo(i * w / 4, 0); g.lineTo(i * w / 4, h); g.stroke();
      g.beginPath(); g.moveTo(0, i * h / 4); g.lineTo(w, i * h / 4); g.stroke();
    }
    for (let i = 0; i < 600; i++) {
      g.fillStyle = `rgba(0,0,0,${Math.random() * 0.05})`;
      g.fillRect(Math.random() * w, Math.random() * h, 3, 3);
    }
  });
  t.wrapS = t.wrapT = THREE.RepeatWrapping; t.repeat.set(9, 2);
  return t;
}
function signTexture(text = 'VERDIA FARMS') {
  return canvasTex(1024, 256, (g, w, h) => {
    g.fillStyle = '#0d3b2e'; g.fillRect(0, 0, w, h);
    g.strokeStyle = '#4ade80'; g.lineWidth = 12; g.strokeRect(16, 16, w - 32, h - 32);
    g.fillStyle = '#d9f99d'; g.font = '800 108px "Baloo 2", sans-serif';
    g.textAlign = 'center'; g.textBaseline = 'middle';
    g.fillText('🌱 ' + text, w / 2, h / 2 - 18);
    g.fillStyle = '#4ade80'; g.font = '700 40px "Baloo 2", sans-serif';
    g.fillText('H I D R O P O N Í A', w / 2, h - 54);
  });
}
function terminalTexture() {
  return canvasTex(512, 320, (g, w, h) => {
    g.fillStyle = '#04180f'; g.fillRect(0, 0, w, h);
    g.fillStyle = '#4ade80'; g.font = '700 34px monospace'; g.fillText('▮ VerdiaOS', 26, 56);
    g.font = '24px monospace'; g.fillStyle = '#22c55e';
    ['> orders board ....... 3', '> pump status ....... OK', '> pH control ........ OK', '> tap to browse_'].forEach((l, i) => g.fillText(l, 26, 120 + i * 46));
  });
}
function marketSignTexture() {
  return canvasTex(512, 160, (g, w, h) => {
    g.fillStyle = '#e11d48'; g.fillRect(0, 0, w, h);
    g.fillStyle = '#fff7ed'; g.font = '800 78px "Baloo 2", sans-serif';
    g.textAlign = 'center'; g.textBaseline = 'middle';
    g.fillText('MERCADO', w / 2, 76);
    g.fillStyle = '#fecdd3'; g.font = '700 34px "Baloo 2", sans-serif';
    g.fillText('F R E S H · L O C A L', w / 2, 126);
  });
}
export function statusTexture(emoji, bg = 'rgba(255,255,255,0.92)') {
  return canvasTex(128, 128, (g) => {
    g.clearRect(0, 0, 128, 128);
    g.fillStyle = bg; g.beginPath(); g.arc(64, 64, 56, 0, Math.PI * 2); g.fill();
    g.strokeStyle = 'rgba(0,0,0,0.18)'; g.lineWidth = 6; g.stroke();
    g.font = '76px serif'; g.textAlign = 'center'; g.textBaseline = 'middle';
    g.fillText(emoji, 64, 70);
  });
}

/* ── materials ───────────────────────────── */
const std = (color, roughness = 0.68, metalness = 0.05) => new THREE.MeshStandardMaterial({ color, roughness, metalness });

/* ── plants ─────────────────────────────── */
export function makePlantMesh(cropDef, growth) {
  const g = new THREE.Group();
  const stage = growth < 15 ? 0 : growth < 50 ? 1 : 2;
  const foliage = std(cropDef.color, 0.72), foliageDark = std(cropDef.dark, 0.75);
  if (stage === 0) {
    const stem = new THREE.Mesh(new THREE.ConeGeometry(0.05, 0.22, 5), foliageDark);
    stem.position.y = 0.11; g.add(stem);
    const leaf = new THREE.Mesh(new THREE.ConeGeometry(0.03, 0.13, 4), foliage);
    leaf.position.set(0.05, 0.14, 0.02); leaf.rotation.z = -0.5; g.add(leaf);
  } else {
    const s = (stage === 1 ? 0.62 : 1) * 0.94;
    if (cropDef.shape === 'leafy') {
      [0.15, 0.32, 0.49].forEach((h, i) => {
        const r = (0.23 - i * 0.06) * s;
        const leaf = new THREE.Mesh(new THREE.ConeGeometry(r, 0.2 * s + 0.05, 8), i % 2 ? foliage : foliageDark);
        leaf.position.y = h * s; leaf.castShadow = true; g.add(leaf);
      });
    } else {
      const bush = new THREE.Mesh(new THREE.IcosahedronGeometry(0.24 * s, 0), foliage);
      bush.scale.y = 0.8; bush.position.y = 0.24 * s; bush.castShadow = true; g.add(bush);
      const bush2 = new THREE.Mesh(new THREE.IcosahedronGeometry(0.15 * s, 0), foliageDark);
      bush2.position.set(0.13 * s, 0.34 * s, 0.06 * s); g.add(bush2);
      if (cropDef.shape === 'fruit' && stage === 2) {
        const fm = std(cropDef.fruit, 0.42);
        const fg = new THREE.SphereGeometry(0.055, 8, 8);
        [[-0.15, 0.16, 0.12], [0.16, 0.25, -0.06], [0.02, 0.14, -0.16]].forEach(p => {
          const f = new THREE.Mesh(fg, fm);
          f.position.set(p[0] * s, p[1] * s + 0.08, p[2] * s); g.add(f);
        });
      }
    }
  }
  return g;
}

