const BUILDERS = {
  growrack: makeGrowRack, raft: makeRaftBed, tower: makeTower,
  tank: makeTank, bench: makeBench, lamp: makeLamp,
  planter: makePlanter, crate: makeCrate, sign: makeSign,
};

export function createModuleModel(type) {
  const b = BUILDERS[type];
  if (!b) return null;
  const { group, slots = [], height } = b();
  group.userData.slots = slots;
  group.userData.height = height;
  const plantsG = new THREE.Group();
  group.add(plantsG);
  group.userData.plantsG = plantsG;
  group.traverse(o => { if (o.isMesh) { o.castShadow = true; o.receiveShadow = true; } });
  return { group, slots, height };
}

