/* ══════════ WORLD BUILD ══════════ */
export function buildWorld(scene) {
  /* lights */
  const hemi = new THREE.HemisphereLight(0xdcf5ff, 0x3d6045, 1.05);
  scene.add(hemi);
  const sun = new THREE.DirectionalLight(0xfff0d2, 2.35);
  sun.position.set(16, 24, 12);
  sun.castShadow = true;
  sun.shadow.mapSize.set(2048, 2048);
  const sc = sun.shadow.camera;
  sc.left = -22; sc.right = 22; sc.top = 22; sc.bottom = -22; sc.near = 1; sc.far = 80;
  sun.shadow.bias = -0.0005;
  sun.shadow.radius = 3;
  scene.add(sun); scene.add(sun.target);
  scene.add(new THREE.AmbientLight(0xffffff, 0.22));

  /* ground */
  const grass = new THREE.Mesh(new THREE.PlaneGeometry(240, 240), new THREE.MeshLambertMaterial({ map: grassTexture() }));
  grass.rotation.x = -Math.PI / 2; grass.receiveShadow = true; scene.add(grass);

  /* patio in front of the plot */
  const patio = new THREE.Mesh(new THREE.PlaneGeometry(30, 6.6), new THREE.MeshLambertMaterial({ map: pavingTexture() }));
  patio.rotation.x = -Math.PI / 2; patio.position.set(0, 0.01, HALF_D + 3.1); patio.receiveShadow = true; scene.add(patio);

  /* slab + floor */
  const slabMat = new THREE.MeshStandardMaterial({ color: 0x7f8c86, roughness: 0.9 });
  const slab = new THREE.Mesh(new THREE.BoxGeometry(FLOOR_W + 0.7, 0.34, FLOOR_D + 0.7), slabMat);
  slab.position.y = -0.17; slab.receiveShadow = true; slab.castShadow = true; scene.add(slab);
  const floorMat = new THREE.MeshLambertMaterial({ map: concreteTexture() });
  const floor = new THREE.Mesh(new THREE.PlaneGeometry(FLOOR_W, FLOOR_D), floorMat);
  floor.rotation.x = -Math.PI / 2; floor.position.y = 0.005; floor.receiveShadow = true; scene.add(floor);

  /* grid lines (visible in build mode) */
  const gridPts = [];
  for (let c = 0; c <= COLS; c++) { const x = -HALF_W + c * TILE; gridPts.push(x, 0.02, -HALF_D, x, 0.02, HALF_D); }
  for (let r = 0; r <= ROWS; r++) { const z = -HALF_D + r * TILE; gridPts.push(-HALF_W, 0.02, z, HALF_W, 0.02, z); }
  const gridGeo = new THREE.BufferGeometry();
  gridGeo.setAttribute('position', new THREE.Float32BufferAttribute(gridPts, 3));
  const grid = new THREE.LineSegments(gridGeo, new THREE.LineBasicMaterial({ color: 0x2f6b4c, transparent: true, opacity: 0.35 }));
  grid.visible = false; scene.add(grid);

  /* invisible floor pick plane */
  const floorHit = new THREE.Mesh(new THREE.PlaneGeometry(FLOOR_W, FLOOR_D), new THREE.MeshBasicMaterial({ visible: false }));
  floorHit.rotation.x = -Math.PI / 2; floorHit.position.y = 0.02; scene.add(floorHit);

  /* back glass walls + frames */
  const frame = std(0x1d5b3c, 0.45, 0.35);
  const glass = new THREE.MeshLambertMaterial({ color: 0xd8f4f8, transparent: true, opacity: 0.22, side: THREE.DoubleSide, depthWrite: false });
  const wallH = 2.5;
  // wall along back (z = -HALF_D)
  const w1 = new THREE.Mesh(new THREE.PlaneGeometry(FLOOR_W + 0.7, wallH), glass);
  w1.position.set(0, wallH / 2, -HALF_D - 0.1); scene.add(w1);
  // wall along left (x = -HALF_W)
  const w2 = new THREE.Mesh(new THREE.PlaneGeometry(FLOOR_D + 0.7, wallH), glass);
  w2.rotation.y = Math.PI / 2; w2.position.set(-HALF_W - 0.1, wallH / 2, 0); scene.add(w2);
  for (let x = -HALF_W; x <= HALF_W; x += TILE * 2.5) {
    const post = new THREE.Mesh(new THREE.BoxGeometry(0.09, wallH, 0.09), frame);
    post.position.set(x, wallH / 2, -HALF_D - 0.1); post.castShadow = true; scene.add(post);
  }
  for (let z = -HALF_D; z <= HALF_D; z += TILE * 2.5) {
    const post = new THREE.Mesh(new THREE.BoxGeometry(0.09, wallH, 0.09), frame);
    post.position.set(-HALF_W - 0.1, wallH / 2, z); post.castShadow = true; scene.add(post);
  }
  [[0, -HALF_D - 0.1, FLOOR_W + 0.7, 0.09], [-HALF_W - 0.1, 0, 0.09, FLOOR_D + 0.7]].forEach(([x, z, w, d]) => {
    const beam = new THREE.Mesh(new THREE.BoxGeometry(w, 0.09, d), frame);
    beam.position.set(x, wallH, z); beam.castShadow = true; scene.add(beam);
  });
  // sign on back wall
  const sign = new THREE.Mesh(new THREE.PlaneGeometry(7, 1.75), new THREE.MeshBasicMaterial({ map: signTexture() }));
  sign.position.set(3.2, 3.4, -HALF_D - 0.05); scene.add(sign);
  // small frame posts for sign
  [-1, 1].forEach(s => {
    const leg = new THREE.Mesh(new THREE.BoxGeometry(0.1, 1.3, 0.1), frame);
    leg.position.set(3.2 + s * 3.2, 2.6, -HALF_D - 0.15); scene.add(leg);
  });
  // front curb
  const curbMat = std(0x8a9a92, 0.85);
  const curb = new THREE.Mesh(new THREE.BoxGeometry(FLOOR_W + 0.7, 0.18, 0.18), curbMat);
  curb.position.set(0, 0.09, HALF_D + 0.28); scene.add(curb);
  [-1, 1].forEach(s => {
    const c2 = new THREE.Mesh(new THREE.BoxGeometry(0.18, 0.18, FLOOR_D + 0.7), curbMat);
    c2.position.set(s * (HALF_W + 0.28), 0.09, 0); scene.add(c2);
  });

  /* trees outside */
  let seed = 4242;
  const rnd = () => { seed = (seed * 16807) % 2147483647; return seed / 2147483647; };
  const trunkMat = new THREE.MeshLambertMaterial({ color: 0x5b3a21 });
  for (let i = 0; i < 22; i++) {
    const a = rnd() * Math.PI * 2, r = 18 + rnd() * 40;
    const x = Math.sin(a) * r, z = Math.cos(a) * r;
    if (z > HALF_D + 4 && Math.abs(x) < 14) continue; // keep patio clear
    const h = 2.4 + rnd() * 2.4;
    const trunk = new THREE.Mesh(new THREE.CylinderGeometry(0.2, 0.29, h * 0.4, 6), trunkMat);
    trunk.position.set(x, h * 0.2, z); trunk.castShadow = true; scene.add(trunk);
    const crown = new THREE.Mesh(new THREE.ConeGeometry(1.1 + rnd() * 0.9, h, 7), new THREE.MeshLambertMaterial({ color: [0x2f6b33, 0x3a7d3e, 0x27592c][i % 3] }));
    crown.position.set(x, h * 0.4 + h * 0.42, z); crown.castShadow = true; scene.add(crown);
  }
  // bushes by patio
  for (let i = 0; i < 10; i++) {
    const x = -13 + rnd() * 26, z = HALF_D + 5.4 + rnd() * 1.4;
    const r = 0.35 + rnd() * 0.35;
    const b = new THREE.Mesh(new THREE.IcosahedronGeometry(r, 0), new THREE.MeshLambertMaterial({ color: [0x2f7d3c, 0x3a8f47, 0x54a85c][i % 3] }));
    b.position.set(x, r * 0.7, z); b.castShadow = true; scene.add(b);
  }

  /* fixed props */
  const market = buildMarket();
  market.position.set(-7.2, 0, HALF_D + 2.6);
  market.rotation.y = 0.12;
  market.userData = { fixed: 'market' };
  scene.add(market);
  const terminal = buildTerminal();
  terminal.position.set(7.2, 0, HALF_D + 2.5);
  terminal.rotation.y = -0.15;
  terminal.userData = { fixed: 'terminal' };
  scene.add(terminal);

  /* daylight */
  const dayColor = new THREE.Color(0x87c7e8);
  function updateDaylight(t) {
    // t 0..1 across 06:00–22:00
    const elev = Math.sin(Math.PI * THREE.MathUtils.clamp(t, 0, 1));
    const az = Math.PI * (0.15 + t * 0.75);
    sun.position.set(Math.cos(az) * 26, 10 + elev * 26, Math.sin(az) * 20 + 4);
    sun.intensity = 0.55 + 2.0 * elev;
    hemi.intensity = 0.6 + 0.55 * elev;
    const warm = new THREE.Color(0xffb37a), noon = new THREE.Color(0xfff3dc), dusk = new THREE.Color(0xff9a63);
    if (t < 0.15) sun.color.copy(warm).lerp(noon, t / 0.15);
    else if (t > 0.85) sun.color.copy(noon).lerp(dusk, (t - 0.85) / 0.15);
    else sun.color.copy(noon);
    return { elev, tint: t < 0.12 ? 0.12 : t > 0.9 ? 0.1 : 0 };
  }

  return {
    hemi, sun, updateDaylight,
    floorHit, grid, floor, market, terminal,
    fixedProps: [market, terminal],
  };
}

/* ══════════ HIDROPONÍA — Android isometric UI ══════════ */
:root {
  --green-deep: #0b3327;
  --green-dark: #0d3b2e;
  --green: #15803d;
  --green-bright: #22c55e;
  --green-light: #86efac;
  --cream: #fbf9ef;
  --cream-2: #f2efdf;
  --ink: #123c2c;
  --ink-soft: #4c6b5c;
  --gold: #f5b91b;
  --gold-deep: #b45309;
  --tomato: #e11d48;
  --nav-h: 64px;
  --safe-b: env(safe-area-inset-bottom, 0px);
  --safe-t: env(safe-area-inset-top, 0px);
}
* { margin: 0; padding: 0; box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
html, body {
  width: 100%; height: 100%; overflow: hidden; position: fixed; inset: 0;
  background: linear-gradient(180deg, #eaf8ea 0%, #cfe9d6 55%, #b3dcc3 100%);
  font-family: 'Nunito', system-ui, sans-serif; color: var(--ink);
  user-select: none; -webkit-user-select: none; touch-action: none;
  overscroll-behavior: none;
}
.hidden { display: none !important; }
canvas { position: fixed; inset: 0; display: block; touch-action: none; }
button { font-family: inherit; border: none; background: none; color: inherit; cursor: pointer; touch-action: manipulation; }
button:active { transform: scale(0.96); }
b { font-weight: 800; }
.dim { opacity: 0.6; }
.dot { margin: 0 5px; opacity: 0.5; }

/* ── scene tint (dawn/dusk) ── */
#scene-tint { position: fixed; inset: 0; pointer-events: none; z-index: 2; transition: background 3s; }

/* ══════════ TOP BAR ══════════ */
#topbar {
  position: fixed; top: 0; left: 0; right: 0; z-index: 30;
  display: flex; justify-content: space-between; align-items: flex-start;
  padding: calc(var(--safe-t) + 8px) 10px 8px 10px;
  pointer-events: none;
}
.cash-block {
  background: rgba(10, 42, 31, 0.88); backdrop-filter: blur(8px);
  border: 1px solid rgba(134, 239, 172, 0.3);
  border-radius: 16px; padding: 7px 14px 6px 12px;
  box-shadow: 0 6px 22px rgba(0, 0, 0, 0.22);
  pointer-events: auto;
}
.cash-line { display: flex; align-items: center; gap: 7px; }
.cash-icon { font-size: 19px; }
#cash {
  font-family: 'Baloo 2'; font-weight: 800; font-size: 25px; line-height: 1;
  color: var(--gold); text-shadow: 0 1px 6px rgba(0,0,0,0.35);
}
.subline { font-size: 10.5px; color: #b8efcd; margin-top: 3px; letter-spacing: 0.2px; }
.top-actions { display: flex; gap: 8px; pointer-events: auto; }
.icon-btn {
  width: 42px; height: 42px; border-radius: 13px;
  background: rgba(10, 42, 31, 0.88); backdrop-filter: blur(8px);
  border: 1px solid rgba(134, 239, 172, 0.3);
  color: #d9f99d; font-size: 19px; display: grid; place-items: center;
  box-shadow: 0 6px 22px rgba(0, 0, 0, 0.22);
}

/* ══════════ TUTORIAL ══════════ */
#tutorial {
  position: fixed; z-index: 25; top: calc(var(--safe-t) + 70px); left: 10px;
  width: 205px; background: rgba(255, 253, 243, 0.96); border: 1.5px solid #b7d9b9;
  border-radius: 14px; padding: 9px 11px; box-shadow: 0 8px 24px rgba(18, 60, 44, 0.18);
  font-size: 11.5px; color: var(--ink);
}
.tut-head { display: flex; justify-content: space-between; align-items: center; font-family: 'Baloo 2'; font-weight: 800; font-size: 12.5px; color: var(--green); margin-bottom: 5px; }
.tut-head button { font-size: 13px; opacity: 0.5; padding: 0 4px; }
.tut-step { display: flex; align-items: center; gap: 5px; padding: 3.5px 0; line-height: 1.2; }
.tut-step .tut-check { color: #9db8a6; font-size: 11px; }
.tut-step b { color: var(--gold-deep); font-size: 10px; margin-left: auto; }
.tut-step.done { opacity: 0.45; text-decoration: line-through; }
.tut-step.done .tut-check { color: var(--green); }
#tutorial.collapsed #tut-list { display: none; }

/* ══════════ TOASTS ══════════ */
#toasts {
  position: fixed; z-index: 35; left: 50%; transform: translateX(-50%);
  top: calc(var(--safe-t) + 74px); width: min(340px, 88vw);
  display: flex; flex-direction: column; gap: 6px; pointer-events: none;
}
.toast {
  background: rgba(12, 48, 35, 0.94); color: #ecfdf5; border-radius: 12px;
  padding: 8px 12px; font-size: 12px; line-height: 1.35; text-align: center;
  border: 1px solid rgba(134, 239, 172, 0.35); box-shadow: 0 6px 20px rgba(0,0,0,0.28);
  animation: toastIn 0.25s ease;
}
.toast.warn { border-color: #fbbf24; }
.toast.bad { border-color: #f87171; }
.toast b { color: #86efac; }
@keyframes toastIn { from { opacity: 0; transform: translateY(-8px); } to { opacity: 1; transform: none; } }

/* ══════════ ZOOM ══════════ */
#zoom-controls {
  position: fixed; z-index: 25; right: 10px;
  bottom: calc(var(--safe-b) + var(--nav-h) + 16px);
  display: flex; flex-direction: column; gap: 7px;
}
#zoom-controls button {
  width: 40px; height: 40px; border-radius: 12px;
  background: rgba(10, 42, 31, 0.82); color: #d9f99d; font-size: 20px; font-weight: 700;
  border: 1px solid rgba(134, 239, 172, 0.3); display: grid; place-items: center;
  backdrop-filter: blur(6px); box-shadow: 0 4px 14px rgba(0,0,0,0.2);
}

/* ══════════ PLACEMENT BAR ══════════ */
#placement-bar {
  position: fixed; z-index: 32; left: 8px; right: 8px;
  bottom: calc(var(--safe-b) + var(--nav-h) + 8px);
  display: flex; align-items: center; gap: 7px;
  background: rgba(255, 253, 243, 0.97); border: 2px solid #86efac;
  border-radius: 16px; padding: 8px 10px;
  box-shadow: 0 10px 30px rgba(10, 42, 31, 0.3);
  animation: barUp 0.22s ease;
}
@keyframes barUp { from { transform: translateY(20px); opacity: 0; } to { transform: none; opacity: 1; } }
#pb-info { display: flex; align-items: center; gap: 8px; flex: 1; min-width: 0; }
#pb-icon { font-size: 26px; }
#pb-name { font-family: 'Baloo 2'; font-weight: 800; font-size: 14px; line-height: 1.1; color: var(--ink); }
#pb-hint { font-size: 10px; color: var(--ink-soft); line-height: 1.2; margin-top: 1px; }
.round-btn {
  width: 42px; height: 42px; border-radius: 12px; font-size: 19px;
  background: var(--cream-2); border: 1.5px solid #cfe3d2; color: var(--green-dark);
  display: grid; place-items: center; flex-shrink: 0;
}
.round-btn.ghost { background: #fdecec; border-color: #f5b5b5; color: #b91c1c; }
.place-confirm {
  min-width: 66px; height: 42px; border-radius: 12px; display: flex; flex-direction: column;
  align-items: center; justify-content: center; line-height: 1; gap: 1px;
  background: var(--green-bright); color: #04281a; font-weight: 800; font-size: 16px;
  box-shadow: 0 4px 12px rgba(34, 197, 94, 0.4);
}
.place-confirm span { font-family: 'Baloo 2'; font-size: 8px; letter-spacing: 1px; }
.place-confirm:disabled { background: #cbd5c9; box-shadow: none; color: #6b7f70; }

/* ══════════ BOTTOM NAV ══════════ */
#bottom-nav {
  position: fixed; z-index: 30; left: 0; right: 0; bottom: 0;
  height: calc(var(--nav-h) + var(--safe-b));
  padding: 5px 4px calc(var(--safe-b) + 5px);
  display: flex; justify-content: space-around; align-items: stretch;
  background: rgba(8, 35, 26, 0.96); backdrop-filter: blur(10px);
  border-top: 1px solid rgba(134, 239, 172, 0.25);
}
#bottom-nav button {
  flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 2px; border-radius: 12px; color: #a7d8bc; font-family: 'Baloo 2'; font-weight: 700;
  font-size: 8.5px; letter-spacing: 0.6px; transition: background 0.15s, color 0.15s;
  max-width: 110px;
}
#bottom-nav .nav-icon { font-size: 21px; line-height: 1; filter: saturate(0.9); }
#bottom-nav button.active { background: rgba(34, 197, 94, 0.18); color: #d9f99d; }
#bottom-nav button:active { transform: none; background: rgba(34, 197, 94, 0.28); }

/* ══════════ SHEET ══════════ */
#sheet-scrim { position: fixed; inset: 0; z-index: 28; background: rgba(4, 22, 15, 0.28); }
#sheet {
  position: fixed; z-index: 29; left: 50%; transform: translateX(-50%);
  bottom: calc(var(--safe-b) + var(--nav-h) + 6px);
  width: min(560px, calc(100vw - 12px)); max-height: 62dvh;
  background: var(--cream); border-radius: 20px;
  border: 1.5px solid #cfe3d2; box-shadow: 0 -8px 40px rgba(4, 30, 20, 0.35);
  display: flex; flex-direction: column;
  animation: sheetUp 0.24s cubic-bezier(0.2, 0.9, 0.3, 1.1);
}
@keyframes sheetUp { from { transform: translate(-50%, 30px); opacity: 0; } to { transform: translate(-50%, 0); opacity: 1; } }
.grab { width: 38px; height: 4px; border-radius: 999px; background: #c5d8c9; margin: 7px auto 0; flex-shrink: 0; }
.sheet-head { display: flex; align-items: center; justify-content: space-between; padding: 6px 16px 6px 16px; flex-shrink: 0; }
.sheet-head h2 { font-family: 'Baloo 2'; font-weight: 800; font-size: 19px; color: var(--green-dark); line-height: 1.1; }
#sheet-close {
  width: 34px; height: 34px; border-radius: 10px; background: #e8efe4;
  color: #476b56; font-size: 15px; display: grid; place-items: center; flex-shrink: 0;
}
#sheet-body { overflow-y: auto; overscroll-behavior: contain; padding: 2px 12px 14px; -webkit-overflow-scrolling: touch; }

/* generic sheet widgets */
.section-title {
  font-family: 'Baloo 2'; font-weight: 800; font-size: 12px; letter-spacing: 1.2px;
  text-transform: uppercase; color: var(--green); margin: 10px 2px 6px;
  display: flex; justify-content: space-between; align-items: center;
}
.big-btn {
  display: flex; align-items: center; justify-content: center; gap: 6px;
  min-height: 50px; padding: 12px 18px; border-radius: 14px;
  background: var(--cream-2); border: 1.5px solid #cfe3d2; color: var(--green-dark);
  font-family: 'Baloo 2'; font-weight: 800; font-size: 15px; letter-spacing: 0.6px;
  width: 100%; box-shadow: 0 3px 0 rgba(18, 60, 44, 0.12);
}
.big-btn.primary { background: linear-gradient(180deg, #34d06a, #16a34a); border-color: #15803d; color: #04281a; box-shadow: 0 4px 0 #0f6b34; }
.big-btn.danger { background: #fdecec; border-color: #f5b5b5; color: #b91c1c; }
.big-btn:disabled { opacity: 0.45; }
.big-btn + .big-btn { margin-top: 8px; }

/* ── build catalog ── */
.build-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.build-card {
  background: #fffef8; border: 1.5px solid #d9e7d4; border-radius: 14px;
  padding: 9px 10px; text-align: left; position: relative; min-height: 104px;
  display: flex; flex-direction: column; box-shadow: 0 2px 0 rgba(18, 60, 44, 0.08);
}
.build-card:active { border-color: var(--green-bright); background: #f2fbf0; }
.build-card .bc-icon { font-size: 25px; line-height: 1.1; }
.build-card .bc-name { font-family: 'Baloo 2'; font-weight: 800; font-size: 13px; line-height: 1.15; color: var(--ink); margin-top: 2px; }
.build-card .bc-desc { font-size: 9.5px; color: var(--ink-soft); line-height: 1.25; margin-top: 2px; flex: 1; }
.build-card .bc-foot { display: flex; justify-content: space-between; align-items: center; margin-top: 5px; }
.bc-size { font-size: 9px; font-weight: 800; background: #e7f3e6; color: #2f6b4c; border-radius: 6px; padding: 2px 5px; }
.bc-cost { font-family: 'Baloo 2'; font-weight: 800; font-size: 13px; color: var(--gold-deep); }
.build-card.locked { opacity: 0.45; }

/* ── rack sheet ── */
.rack-status {
  display: flex; align-items: center; gap: 10px; background: #eef7ec; border-radius: 12px;
  padding: 9px 11px; margin-top: 4px;
}
.rack-status .rs-icon { font-size: 30px; }
.rack-status .rs-main { flex: 1; min-width: 0; }
.rack-status .rs-name { font-family: 'Baloo 2'; font-weight: 800; font-size: 15px; line-height: 1.1; }
.rack-status .rs-sub { font-size: 10.5px; color: var(--ink-soft); margin-top: 1px; }
.rack-status .rs-chip { font-family: 'Baloo 2'; font-size: 10px; font-weight: 800; border-radius: 8px; padding: 4px 8px; background: #d9f2d6; color: #166534; white-space: nowrap; }
.rack-status .rs-chip.warn { background: #fef3c7; color: #92400e; }
.rack-status .rs-chip.bad { background: #fee2e2; color: #b91c1c; }

.bars { display: grid; grid-template-columns: 1fr 1fr; gap: 6px 12px; margin: 9px 2px 4px; }
.bar-row { display: flex; align-items: center; gap: 6px; }
.bar-row .bl { width: 46px; font-size: 9.5px; color: var(--ink-soft); font-weight: 700; }
.bar { flex: 1; height: 9px; background: #e2e9de; border-radius: 999px; overflow: hidden; }
.bar > i { display: block; height: 100%; border-radius: 999px; transition: width 0.3s; }
.bar .grow { background: linear-gradient(90deg, #4ade80, #16a34a); }
.bar .water { background: linear-gradient(90deg, #38bdf8, #0369a1); }
.bar .nutr { background: linear-gradient(90deg, #c084fc, #7e22ce); }
.bar .health { background: linear-gradient(90deg, #fda4af, #e11d48); }
.bar-text { font-family: 'Baloo 2'; font-size: 11px; font-weight: 800; color: var(--ink); margin: 7px 2px 0; }
.ph-badge { font-family: 'Baloo 2'; font-weight: 800; font-size: 11px; padding: 4px 8px; border-radius: 8px; background: #e7f3e6; }
.ph-badge.bad { background: #fee2e2; color: #b91c1c; }

.seed-row { display: flex; gap: 7px; overflow-x: auto; padding: 4px 2px 6px; scrollbar-width: none; }
.seed-row::-webkit-scrollbar { display: none; }
.seed-chip {
  flex: 0 0 auto; min-width: 66px; background: #fffef8; border: 1.5px solid #d9e7d4;
  border-radius: 12px; padding: 7px 9px 6px; text-align: center;
}
.seed-chip:active { border-color: var(--green-bright); }
.seed-chip .sc-icon { font-size: 22px; line-height: 1; }
.seed-chip .sc-name { font-family: 'Baloo 2'; font-weight: 800; font-size: 10px; margin-top: 2px; line-height: 1.1; }
.seed-chip .sc-count { font-size: 9px; color: var(--green); font-weight: 800; }
.seed-chip.empty { opacity: 0.4; }

.action-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 7px; margin-top: 8px; }
.action-btn {
  min-height: 48px; border-radius: 12px; background: #fffef8; border: 1.5px solid #d9e7d4;
  display: flex; align-items: center; gap: 8px; padding: 7px 10px; text-align: left;
  box-shadow: 0 2px 0 rgba(18, 60, 44, 0.08);
}
