.empty-state .es-icon { font-size: 30px; display: block; margin-bottom: 6px; }

/* ── orders ── */
.order-card { background: #fffef8; border: 1.5px solid #d9e7d4; border-radius: 13px; padding: 10px 11px; margin-bottom: 8px; }
.order-card .oc-client { font-family: 'Baloo 2'; font-weight: 800; font-size: 13px; color: #92400e; }
.order-card .oc-detail { font-size: 12px; margin: 2px 0; }
