.order-card .oc-deadline { font-size: 10px; color: var(--ink-soft); }
.order-card .oc-actions { margin-top: 7px; display: flex; gap: 7px; }
.oc-btn {
  flex: 1; min-height: 40px; border-radius: 10px; background: var(--green); color: #eafff2;
  font-family: 'Baloo 2'; font-weight: 800; font-size: 12px; box-shadow: 0 3px 0 #0b5c2d;
}
.oc-btn.alt { background: #eef3ea; color: #335744; border: 1.5px solid #d9e7d4; box-shadow: none; }
.oc-btn:disabled { opacity: 0.4; box-shadow: none; }

/* ── shop ── */
.shop-row {
  display: flex; align-items: center; gap: 9px; background: #fffef8; border: 1.5px solid #d9e7d4;
  border-radius: 13px; padding: 8px 10px; margin-bottom: 7px;
}
.shop-row .sh-icon { font-size: 23px; width: 30px; text-align: center; }
.shop-row .sh-main { flex: 1; min-width: 0; }
.shop-row .sh-name { font-family: 'Baloo 2'; font-weight: 800; font-size: 12.5px; line-height: 1.15; }
.shop-row .sh-desc { font-size: 9.5px; color: var(--ink-soft); line-height: 1.25; }
.shop-row .sh-btn {
  min-width: 62px; min-height: 38px; border-radius: 10px; background: var(--green); color: #eafff2;
  font-family: 'Baloo 2'; font-weight: 800; font-size: 12px; box-shadow: 0 3px 0 #0b5c2d; padding: 0 9px;
}
.shop-row .sh-btn.owned { background: #fef3c7; color: #92400e; box-shadow: none; }
.shop-row .sh-btn:disabled { opacity: 0.4; box-shadow: none; }

/* ── day sheet ── */
.stat-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 7px; margin: 6px 0; }
.stat-box { background: #fffef8; border: 1.5px solid #d9e7d4; border-radius: 12px; padding: 8px 10px; }
.stat-box .sb-label { font-size: 9px; letter-spacing: 0.7px; text-transform: uppercase; color: var(--ink-soft); font-weight: 800; }
.stat-box .sb-value { font-family: 'Baloo 2'; font-weight: 800; font-size: 17px; color: var(--green-dark); }
.price-grid { display: flex; flex-wrap: wrap; gap: 6px; margin: 4px 0 8px; }
.price-pill { background: #fffef8; border: 1.5px solid #d9e7d4; border-radius: 999px; padding: 4px 9px; font-size: 11px; font-weight: 700; }
.price-pill b { color: var(--gold-deep); }
.daytip { font-size: 11px; color: var(--ink-soft); line-height: 1.45; background: #eef7ec; border-radius: 10px; padding: 8px 10px; margin-top: 8px; }

/* ══════════ TITLE ══════════ */
.screen { position: fixed; inset: 0; z-index: 40; display: flex; align-items: center; justify-content: center; }
#title-screen { background: linear-gradient(180deg, rgba(4, 26, 17, 0.72) 0%, rgba(8, 42, 30, 0.35) 40%, rgba(4, 26, 17, 0.82) 100%); overflow: hidden; }
.title-glow { position: absolute; inset: 0; pointer-events: none; background: radial-gradient(ellipse at 50% 115%, rgba(34, 197, 94, 0.4), transparent 60%); }
.title-inner { position: relative; text-align: center; z-index: 2; padding: 16px; width: 100%; max-width: 430px; animation: fadeUp 0.8s ease; }
@keyframes fadeUp { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: none; } }
.brand { font-family: 'Baloo 2'; letter-spacing: 3px; font-size: 11px; color: #a7f3d0; margin-bottom: 4px; }
.game-title {
  font-family: 'Baloo 2'; font-weight: 800; font-size: clamp(48px, 15vw, 84px); line-height: 0.92;
  background: linear-gradient(180deg, #ecfccb 0%, #86efac 35%, #22c55e 70%, #15803d 100%);
  -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent;
  letter-spacing: 1px; filter: drop-shadow(0 6px 30px rgba(34, 197, 94, 0.35));
}
.game-subtitle { font-family: 'Baloo 2'; font-size: 10.5px; letter-spacing: 2px; color: #bbf7d0; opacity: 0.85; margin: 8px 0 26px; }
.title-menu { display: flex; flex-direction: column; gap: 10px; align-items: center; }
.title-menu .big-btn { max-width: 330px; }
.title-foot { margin-top: 24px; font-size: 10px; color: #b8efcd; opacity: 0.75; line-height: 1.5; }

/* ══════════ OVERLAYS (help / sleep) ══════════ */
.overlay {
  position: fixed; inset: 0; z-index: 50; display: flex; align-items: center; justify-content: center;
  background: rgba(4, 20, 13, 0.72); backdrop-filter: blur(5px); padding: 14px;
}
.overlay-card {
  background: var(--cream); border-radius: 20px; padding: 20px 18px;
  width: min(430px, 96vw); max-height: 88dvh; display: flex; flex-direction: column;
  box-shadow: 0 24px 80px rgba(0, 0, 0, 0.5); border: 1.5px solid #cfe3d2;
  animation: fadeUp 0.25s ease;
}
.overlay-card.wide { width: min(560px, 96vw); }
.overlay-card h2 { font-family: 'Baloo 2'; font-weight: 800; font-size: 22px; color: var(--green-dark); margin-bottom: 10px; flex-shrink: 0; }
.help-scroll { overflow-y: auto; overscroll-behavior: contain; flex: 1; padding-right: 3px; margin-bottom: 12px; }
.help-scroll h3 { font-family: 'Baloo 2'; font-size: 14px; color: var(--green); margin: 12px 0 4px; }
.help-scroll p, .help-scroll li { font-size: 12.5px; line-height: 1.5; color: #2c4c3d; }
.help-scroll ul { padding-left: 18px; }
.help-scroll li { margin: 2px 0; }
.help-scroll b { color: var(--green-dark); }
.sleep-summary { background: #eef7ec; border-radius: 13px; padding: 12px 14px; margin-bottom: 14px; font-size: 13px; line-height: 2; }

/* ══════════ MILESTONE ══════════ */
#milestone-toast { position: fixed; z-index: 60; top: calc(var(--safe-t) + 76px); left: 50%; transform: translateX(-50%); width: min(340px, 90vw); }
.milestone-inner {
  display: flex; gap: 12px; align-items: center; padding: 12px 18px; border-radius: 16px;
  background: linear-gradient(135deg, #422006, #854d0e); border: 2px solid var(--gold);
  box-shadow: 0 0 50px rgba(251, 191, 36, 0.45); animation: fadeUp 0.4s ease;
}
.milestone-star { font-size: 34px; animation: pulse 1s infinite alternate; }
@keyframes pulse { from { transform: scale(1) rotate(-4deg); } to { transform: scale(1.15) rotate(5deg); } }
.ms-label { font-size: 8px; letter-spacing: 1.5px; color: #fde68a; }
#milestone-name { font-family: 'Baloo 2'; font-weight: 800; font-size: 17px; color: var(--gold); line-height: 1.1; }
#milestone-reward { font-size: 10px; color: #fef3c7; opacity: 0.8; }

#rotate-hint { display: none; }
@media (pointer: coarse) and (orientation: portrait) {
  #rotate-hint {
    display: block; position: fixed; z-index: 15; bottom: calc(var(--safe-b) + var(--nav-h) + 4px);
    left: 50%; transform: translateX(-50%); font-size: 8.5px; color: rgba(18, 60, 44, 0.5);
    pointer-events: none; white-space: nowrap;
  }
}

/* ══════════ LANDSCAPE / SMALL HEIGHT ══════════ */
@media (max-height: 520px) {
  :root { --nav-h: 54px; }
  #topbar { padding-top: calc(var(--safe-t) + 4px); }
  #cash { font-size: 21px; }
  .cash-block { padding: 5px 11px; }
  .subline { font-size: 9.5px; }
  #topbar .icon-btn { width: 36px; height: 36px; font-size: 16px; }
  #tutorial { width: 180px; font-size: 10px; top: calc(var(--safe-t) + 56px); }
  #zoom-controls { bottom: calc(var(--safe-b) + var(--nav-h) + 10px); }
  #zoom-controls button { width: 34px; height: 34px; font-size: 17px; }
  #sheet { max-height: 74dvh; width: min(500px, calc(100vw - 150px)); right: 8px; left: auto; transform: none; }
  @keyframes sheetUp { from { transform: translateY(30px); opacity: 0; } to { transform: none; opacity: 1; } }
  #toasts { top: 8px; left: auto; right: 100px; transform: none; width: 250px; }
  #tutorial { display: none; }
}

content.text:
Now main.js — the biggest part. Let me plan the code structure precisely.

```js
import * as THREE from 'three';
import { buildWorld, createModuleModel, makePlantMesh, makeFootprintHighlight, statusTexture,
         TILE, COLS, ROWS, FLOOR_W, FLOOR_D, tileCenter, moduleCenter, worldToTile } from './world.js';
import { CROPS, CROP_IDS, MODULES, UPGRADES, MILESTONES, rollPrices, rollContractOffers, netWorth } from './data.js';
import { sfx, setMuted, isMuted } from './audio.js';
```

Constants: DAY_LEN=210, DAY_START, DAY_END, SAVE_KEY='hidroponia.iso.v2'.

State default:
```js
{
 cash: 900, day: 1, timeMin: DAY_START,
 seeds: {lettuce:3, kale:2, basil:2, tomato:1, strawberry:1},
 produce: zeros,
 nutrient: 2, pesticide: 1,
 upgrades: {led1:false,led2:false,autoWater:false,autoDose:false,contracts:false,market:false,solar:false},
 prices: rollPrices(),
 offers: rollContractOffers(1),
 activeContracts: [],
 milestonesClaimed: [],
 dayStats: {earned:0,spent:0,harvested:0},
 tutorial: {placed:false, planted:false, sold:false, collapsed:false, rewardClaimed:false},
 nextId: 1,
}
```
Modules stored separately in `modules = []` with `data`. Serialization includes modules.

Camera:
```js
const VIEW_H = 24;
camera = new THREE.OrthographicCamera(-1,1,1,-1,0.1,200);
camera.position... set by target + offset
const camTarget = new THREE.Vector3(-1, 0, 0.5);
let camZoom = 1;
const YAW = Math.PI/4, PITCH = 0.72; // ~41deg
function updateCamera() {
  const dist=60;
  const off = new THREE.Vector3(Math.sin(YAW)*Math.cos(PITCH), Math.sin(PITCH), Math.cos(YAW)*Math.cos(PITCH)).multiplyScalar(dist);
  camera.position.copy(camTarget).add(off);
  camera.lookAt(camTarget);
  camera.zoom = camZoom;
  camera.updateProjectionMatrix();
}
```
PITCH 0.72 rad = 41°; sin 0.659, cos 0.752 → camera y ≈ 39.5, horizontal dist ≈ 45. Ortho near/far 0.1/200 covers. Fine.

Resize: aspect; camera.left=-VIEW_H*aspect/2 etc. Actually simpler: set left/right/top/bottom once: top=VIEW_H/2, bottom=-VIEW_H/2, left=-VIEW_H*aspect/2, right=+VIEW_H*aspect/2. Then zoom. On resize update.

Default zoom by aspect: portrait (aspect<1): 1.15; landscape: 0.9? Let's compute visible world height at zoom z: VIEW_H / z. At portrait z=1.15 → 20.9 units vertical; width = 20.9*0.46=9.6 — shows about 6 tiles wide; good for detail, pan needed. Whole farm view requires zoom 0.55 → 43.6 height (fits 36) and width 20 (still less than 28 for whole width in portrait, so whole farm never fits in portrait width; okay).

Better initial portrait zoom 0.9 to see more: height 26.7, width 12.3. Racks ~3 tiles visible. I'll set default: portrait 1.0, landscape 0.85. Start camTarget near preplaced racks (0, 0, 0) center.

Pan clamp: target x [-8,8], z [-6,10]. Actually camera target with iso projection allows seeing outside; clamp modestly. On portrait, pan to see patio at z=10 and back wall at z=-8. Set x ∈ [-9,9], z ∈ [-7.5,10.5].

Zoom clamp: 0.55..2.0.

Module models: `createModuleModel(type)` returns {group, slots, height} with plantsG inside. Wrap:
```js
function computeFootprint(type, rot) {
  const def = MODULES[type];
  const w = rot % 2 === 0 ? def.w : def.h;
  const h = rot % 2 === 0 ? def.h : def.w;
  return {w,h};
}
```

Occupancy map: use array of arrays or Set of "c,r". `isAreaFree(col,row,w,h, excludeId)`.

placeModule({type,col,row,rot,data,silent}):
```js
const def = MODULES[type]; const fp = computeFootprint(type,rot);
if (!valid area) return null;
const {group, slots, height} = createModuleModel(type);
const {x,z} = moduleCenter(col,row,fp.w,fp.h);
group.position.set(x,0,z); group.rotation.y = rot*Math.PI/2;
if (type === 'lamp' && lampCount>=4) { remove point light from group? } // cap: traverse find PointLight and remove if limit.
const id = state.nextId++;
group.traverse(o => { o.userData.moduleId = id; });
scene.add(group);
const m = {id,type,col,row,rot,group,slots,fp,data: data || defaultModuleData(type)};
m.statusSprite = makeStatusSprite(); group.add(m.statusSprite); // y height+0.35
if (type==='lamp') lampLights++;
modules.push(m);
refreshModuleVisual(m, true);
if (!silent) { spend(def.cost); ... tutorial...}
```
Data for grow modules:
```js
{crop:null, growth:0, water:80, nutr:60, ph:6.5, health:100, pests:false, broken:false, readyNotified:false}
```
For decor, data {}.

`refreshModuleVisual(m, force)`:
- if grow: stage/crop change → rebuild plants from m.slots (local coords from world factory); each plant = makePlantMesh(def, growth), position copy slot. Scale? already ~0.94. Add to group.userData.plantsG.
- LED materials: find meshes with material.emissive? Instead have group.userData.ledMats collected? Not set in factories. Simpler: broken modules tint? For broken, we can hide LED glow by traversing meshes whose material.emissiveIntensity>1 and set to 0.05. Store original? Let's add in factory userData.ledMats arrays — didn't. I can find by material.emissive check:
```js
group.traverse(o=>{ if(o.isMesh && o.material && o.material.emissiveIntensity > 1.5) o.material.emissiveIntensity = d.broken?0.05:2.2; })
```
Good enough (LED bars + tower cap).
- status sprite: sprite.material.map = statusTexture(emoji); need precreated textures: readyTex(✨), pestTex(🐛), brokenTex(⚡). Assign and set visible.
- sprite bob in render loop.

Sprite creation:
```js
function makeStatusSprite() {
  const mat = new THREE.SpriteMaterial({ map: readyTex, transparent: true, depthTest: false });
  const s = new THREE.Sprite(mat); s.scale.set(0.62,0.62,1); s.position.y = 2.45; s.visible=false; s.renderOrder=10; return s;
}
```
Status per frame: growing → hide sprite (or show water droplet if water low? Show ⚠️ if water < 15 or nutr < 10 or health < 35; good info!). Priorities: broken ⚡, pests 🐛, ready ✨, low water 💧? Use: broken > pests > ready > (water<20 || nutr<15) ? 💧 : hidden. Emoji texture for 💧 too. statusTextures = {ready: statusTexture('✨'), pest: statusTexture('🐛'), broken: statusTexture('⚡'), thirst: statusTexture('💧'), ok: statusTexture('✅')}. I'll show '✅' for ready actually clearer than ✨. Use ready '✅'.

Growth sim:
- Iterate modules where def.kind==='grow' && data.crop.
- drains water 1.0/s (autoWater reduces to 0.3 + refill), nutr 0.6/s, autoDose.
- pH drift random; health etc. Same as before.
- Growth rate: base 100/growTime * def.growth * ledBonus * lampBoost * (health/100 floor 0.3) * phOK...
- lampBoost: any lamp within Chebyshev tile distance <= 2 → 1.1.
- ready toast + tutorial? no.
- death.
- Events daily: pests 40% on random grow module with crop; broken 15%.

Lamp light cap: in placeModule count existing lamps; if >=4 remove PointLight: `group.traverse` can't remove during traverse safely; collect lights then `light.parent.remove(light)`.

Interactions/sheets:
- openSheet(name, module?) — could be nav sheet or rack sheet. `activeSheet = {name, moduleId?}`. DOM update.
- renderSheet() switch.

Screens: 'title' | 'playing' | 'sleep' | 'help'. Sheets don't pause sim.

Nav active states; if sheet open and nav tapped same → close.

Canvas tap logic:
```js
function handleTap(x,y){
  if (isPlacing) { selectGhostCell(x,y); return; }
  const ray = set from camera with ndc;
  const hits = ray.intersectObjects([...modules.map(m=>m.group), ...world.fixedProps], true);
  if (hits.length) {
    let o=hits[0].object; while (o && !o.userData.moduleId && !o.userData.fixed) o=o.parent;
    if (o?.userData.moduleId) { selectModule(o.userData.moduleId); return; }
    if (o?.userData.fixed) { openSheet(o.userData.fixed); sfx.blip(); return; }
  }
  // floor?
  const fh = ray.intersectObject(world.floorHit)[0];
  if (fh) { deselect(); closeSheet(); }
  else { deselect(); closeSheet(); }
}
```
Note: tap on module while placement mode is active should also place? Ghost placement uses floorHit ray only — modules could block the floor ray! If tapping an occupied tile, ray hits module first, not floor → selectGhostCell won't get floor hit. For ghost placement, better raycast the floor plane mathematically: ray-plane intersection with y=0.02 always works regardless of objects:
```js
const ndc; raycaster.setFromCamera; const plane = new THREE.Plane(new Vector3(0,1,0), -0.02);
const point = new THREE.Vector3(); raycaster.ray.intersectPlane(plane, point);
```
Then convert to tile. Use that for ghost. ✓

Ghost:
```js
let placing = null; // {type, rot, ghost, col,row, valid, highlight}
startPlacing(type) { if(cash<cost) toast; else create ghost model; hide sheet; update placement bar; grid.visible=true; }
```
Ghost group: model clone with ghost materials. `createModuleModel(type)` creates new model then traverse replace materials: dispose old? Not necessary for temporary; but geometry shared? each factory creates geometry per instance; ghost disposal on cancel to avoid leak. Implement `applyGhostMaterial(group)`:
```js
group.traverse(o=>{ if(o.isMesh){ o.material = ghostMat; o.castShadow=false; } if (o.isPointLight) o.visible=false; });
```
Also hide plants group.

Ghost highlight: use makeFootprintHighlight(0x4ade80) scaled to fp; when invalid set colors red. `hl.userData.plane.material.color.setHex(...)` and border.

Position ghost at moduleCenter, rotation rot*PI/2. Initially place at grid center? Show ghost only after tap; initially hidden. Placement bar hint "Toca una celda del suelo". When tap: ghost.visible = true; confirm enabled if valid. If tap invalid (out of bounds/occupied) → red highlight; confirm disabled.

Confirm: if valid & cash>=cost → placeModule with charges; keep placing; hide ghost; reset confirm disabled; update bar cost; toast; tutorial placed; close? Keep mode. If cash < cost toast error and exit? Keep.

Exit placing: remove ghost, highlight, grid hidden, placement bar hidden, activeSheet=null? Keep nav normal.

Rotate: placing.rot = (rot+1)%2; if ghost visible, update footprint + highlight validity.

Placed module sheet:
- openModuleSheet(id): selectedId; highlight selection; renderRackSheet or utility sheet.
- Selection highlight: footprintHighlight with gold color at module center; hide when deselected/close.
- Actions via delegated data-action attributes.

Sheet HTML for rack:
```
STATUS card: icon 🥬/🌿 + name + sub ("Listo para cosechar" etc) + chip (growth%)
Bars: growth not needed as bar? show bar text "Crecimiento 62%" + bars water/nutrients/health; pH badge.
If empty: seed-row chips (data-action="plant" data-crop)
If crop: actions grid: water, feed, ph, spray (spray warn if pests); harvest big if ready.
If broken: repair button.
mini-actions: rotate (↻), sell.
```
For utility:
- tank: text + button "Regar todos los racks" (data-action="refill")
- bench: "Preparar nutrientes +2 ($25)" (data-action="mix")
- lamp: info boost; maybe toggle? no.
- decor: description.
mini-actions rotate/sell for all.

Sheet live update: every 400ms if activeSheet.name==='rack' → update bars and chip text via IDs, so no rebuild. I'll implement `refreshRackSheetLive()` selecting elements by id. Need stable ids: #rs-chip, #bar-growth? I'll display growth as bar too (4 bars in grid). Actually 4 bars: growth, water, nutrients, health. Use ids bar-g, bar-w, bar-n, bar-h, text values in labels? Keep bar plus % text small. Simpler: bars with labels + no numbers except status chip shows "62%". Add pH badge.

For live updates only when sheet open. Rebuild triggers on actions (harvest/plant) via renderSheet again.

Market sheet: rows for produce > 0 (with qty and price), totals, "VENDER TODO". Also maybe show seeds no. Sell one row.
Sell all triggers tutorial sold.
Orders sheet: active contracts + offers; accept/deliver. Max active 4.
Shop sheet: seeds (buy 1 with cost, maybe +5 button? Mobile space: each row buy 1 and buy 5 smaller? Keep tap = +1 seed, long? Use two buttons: "$8" and "×5 $40" for seeds. That's wide; in portrait row: icon, name + desc, two small buttons. OK.)
Supplies: pesticide $18, nutrient +2 $25.
Upgrades list.
Day sheet: stats + prices + "TERMINAR DÍA" big button + milestone info.
Menu sheet: save, help, fullscreen, mute, quit to title.

Tutorial:
- check per step; when step completes first time: cash += 50, toast "✅ Paso completado +$50"; mark; if all 3 → hide with delay, toast.
- collapsed toggle persists.
- should only show when playing & not complete.
- markStep(step).

Fullscreen:
```js
function toggleFullscreen() {
  if (!document.fullscreenElement) document.documentElement.requestFullscreen?.().catch(()=>{});
  else document.exitFullscreen?.();
}
```

Sleep:
- auto when timeMin >= DAY_END → showSleep().
- showSleep sets screen='sleep'; close sheets/placement; fills summary; shows overlay.
- nextDay(): deduct cost, expire contracts, day++, prices, offers, dayStats reset, events, save, hide, screen='playing'.
- Day sheet "Terminar día" → open sleep summary early. Time resets on nextDay.
- If sleeping via button, no auto 22:00 double-trigger since screen changes.
- manual time: dt*TIME_SCALE.

Save/load:
- serialize state + modules (id,type,col,row,rot,data).
- load: clear existing modules (dispose groups), state=merge, placeModule for each with silent + data; applyUpgrades? No expansion upgrade needed. lamp lights recount.
- Ensure camera target reset.
- localStorage key v2.
- New game: clear modules; preplace starter: use a helper after resetting with cash 900 and no charge. Preplace:
  - growrack at col 3,row 3 rot 0 (cols 3-4, row 3)
  - growrack at col 3,row 5 rot 0
  - tank at col 6,row 2
  - bench at col 6,row 4
  - planter at col 8,row 3
  - crate at col 8,row 5
  - sign at col 1,row 2
  Cash 900. Starter layout centered-left to leave room.
- after preplace, maybe preselect tutorial & show.
- New game sets state tutorial defaults then startPlaying.

Persistence of tutorial in state.

Title mode:
- camera slowly drifts target x/z over time, zoom 0.75; show scene.
- title buttons.

Renderer:
```js
renderer = new THREE.WebGLRenderer({antialias:true, alpha:true});
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.outputColorSpace default; toneMapping ACES; exposure 1.05; shadowMap enabled PCFSoft.
document.body.insertBefore(renderer.domElement, document.body.firstChild) — ensure z-index behind UI: canvas fixed inset 0, default z auto (0). #scene-tint z 2, topbar 30 etc. good.
```
Set canvas style touchAction none.

Pointer handling:
```js
const pointers = new Map();
let dragStart=null, moved=false, pinchStart=null;
canvas.addEventListener('pointerdown', e => {
  canvas.setPointerCapture(e.pointerId);
  pointers.set(e.pointerId, {x:e.clientX,y:e.clientY});
  if (pointers.size===1) { dragStart={x,y,t:performance.now(), target:{...camTarget}}; moved=false; }
  if (pointers.size===2) { const [a,b]=[...pointers.values()]; pinchStart={dist:Math.hypot(a.x-b.x,a.y-b.y), zoom:camZoom}; dragStart=null; }
  if (screen==='playing') ensureAudio(); // sound unlock
});
canvas.addEventListener('pointermove', e => {
  if (!pointers.has(e.pointerId)) return;
  const prev = pointers.get(e.pointerId); pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});
  if (pointers.size===1 && dragStart) {
