// ══════════ HIDROPONÍA — isometric Android sandbox ══════════
import * as THREE from 'three';
import {
  buildWorld, createModuleModel, makePlantMesh, makeFootprintHighlight, statusTexture,
  TILE, COLS, ROWS, FLOOR_W, FLOOR_D, moduleCenter, worldToTile,
} from './world.js';
import { CROPS, CROP_IDS, MODULES, UPGRADES, MILESTONES, rollPrices, rollContractOffers, netWorth } from './data.js';
import { sfx, setMuted, isMuted, unlockAudio } from './audio.js';

const $ = (id) => document.getElementById(id);
const DAY_LEN = 210;
const DAY_START = 6 * 60, DAY_END = 22 * 60;
const TIME_SCALE = (DAY_END - DAY_START) / DAY_LEN;
const SAVE_KEY = 'hidroponia.iso.v2';
const VIEW_H = 24;
const MIN_ZOOM = 0.55, MAX_ZOOM = 2.1;

/* ═══════════ STATE ═══════════ */
const defaultState = () => ({
  cash: 900, day: 1, timeMin: DAY_START,
  seeds: { lettuce: 3, kale: 2, basil: 2, tomato: 1, strawberry: 1 },
  produce: { lettuce: 0, kale: 0, basil: 0, tomato: 0, strawberry: 0 },
  nutrient: 2, pesticide: 1,
  upgrades: { led1: false, led2: false, autoWater: false, autoDose: false, contracts: false, market: false, solar: false },
  prices: rollPrices(),
  offers: rollContractOffers(1),
  activeContracts: [],
  milestonesClaimed: [],
  dayStats: { earned: 0, spent: 0, harvested: 0 },
  tutorial: { placed: false, planted: false, sold: false, collapsed: false },
  nextId: 1,
});

let state = defaultState();
let modules = [];
let scene, camera, renderer, world, clock;
let screen = 'title';
let activeSheet = null;         // 'build' | 'market' | 'orders' | 'shop' | 'day' | 'menu' | 'rack' | 'utility' | 'marketprop' ...
let selectedId = null;
let placing = null;
let camTarget = new THREE.Vector3(-1.2, 0, 0.6);
let camZoom = 1;
let helpReturn = 'title';
let sellArmed = null;

const YAW = Math.PI / 4, PITCH = 0.72, CAM_DIST = 60;
const camOffset = new THREE.Vector3(
  Math.sin(YAW) * Math.cos(PITCH), Math.sin(PITCH), Math.cos(YAW) * Math.cos(PITCH)
).multiplyScalar(CAM_DIST);

const statusTex = {
  ready: statusTexture('✅'),
  pest: statusTexture('🐛'),
  broken: statusTexture('⚡'),
  thirst: statusTexture('💧'),
};
const ghostMat = new THREE.MeshBasicMaterial({ color: 0x4ade80, transparent: true, opacity: 0.42, depthWrite: false });
const raycaster = new THREE.Raycaster();
const pointerNdc = new THREE.Vector2();
const floorPlane = new THREE.Plane(new THREE.Vector3(0, 1, 0), -0.02);
const selHighlight = makeFootprintHighlight(0xfbbf24);
selHighlight.visible = false;
const tempVec = new THREE.Vector3();

/* ═══════════ BOOT ═══════════ */
function init() {
  renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true, powerPreference: 'high-performance' });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.06;
  renderer.domElement.id = 'game-canvas';
  document.body.prepend(renderer.domElement);

  scene = new THREE.Scene();
  camera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0.1, 220);
  camera.position.copy(camTarget).add(camOffset);
  camera.lookAt(camTarget);
  scene.add(selHighlight);

  world = buildWorld(scene);
  setViewport();
  updateCamera();

  clock = new THREE.Clock();
  bindUI();
  bindTouch();

  window.addEventListener('resize', onResize);
  window.addEventListener('orientationchange', () => setTimeout(onResize, 250));

  $('btn-continue').style.visibility = localStorage.getItem(SAVE_KEY) ? 'visible' : 'hidden';
  const params = new URLSearchParams(window.location.search);
  if (params.get('autostart') === '1') newGame(false);
  else renderTitle();
}

function setViewport() {
  const w = window.innerWidth, h = window.innerHeight;
  const aspect = w / h;
  const top = VIEW_H / 2, bottom = -VIEW_H / 2;
  const left = -(VIEW_H * aspect) / 2, right = (VIEW_H * aspect) / 2;
  camera.left = left; camera.right = right; camera.top = top; camera.bottom = bottom;
  camera.updateProjectionMatrix();
}
function onResize() {
  renderer.setSize(window.innerWidth, window.innerHeight);
  setViewport();
  updateCamera();
}
function updateCamera() {
  camTarget.x = THREE.MathUtils.clamp(camTarget.x, -9.5, 9.5);
  camTarget.z = THREE.MathUtils.clamp(camTarget.z, -7.5, 11);
  camera.position.copy(camTarget).add(camOffset);
  camera.lookAt(camTarget);
  camera.zoom = camZoom;
  camera.updateProjectionMatrix();
  camera.updateMatrixWorld();
}

/* ═══════════ SAVE / LOAD ═══════════ */
function serialize() {
  return JSON.stringify({
    ...state,
    modules: modules.map(m => ({ id: m.id, type: m.type, col: m.col, row: m.row, rot: m.rot, data: m.data })),
  });
}
function saveGame(showToast = true) {
  try {
    localStorage.setItem(SAVE_KEY, serialize());
    $('btn-continue').style.visibility = 'visible';
    if (showToast) toast('💾 Partida guardada');
  } catch (e) { toast('No se pudo guardar', 'bad'); }
}
function loadGame() {
  try {
    const raw = localStorage.getItem(SAVE_KEY);
    if (!raw) return false;
    const s = JSON.parse(raw);
    const mods = s.modules || [];
    delete s.modules;
    state = { ...defaultState(), ...s };
    state.upgrades = { ...defaultState().upgrades, ...(s.upgrades || {}) };
    state.tutorial = { ...defaultState().tutorial, ...(s.tutorial || {}) };
    clearAllModules();
    for (const rec of mods) {
      placeModule(rec.type, rec.col, rec.row, rec.rot || 0, rec.data, { silent: true, free: true, id: rec.id });
    }
    state.nextId = Math.max(state.nextId || 1, ...mods.map(m => (m.id || 0) + 1), 1);
    selHighlight.visible = false;
    selectedId = null;
    return true;
  } catch (e) { console.error(e); return false; }
}
function clearAllModules() {
  for (const m of modules) {
    scene.remove(m.group);
    disposeGroup(m.group);
  }
  modules = [];
}

/* ═══════════ MODULES ═══════════ */
function footprint(type, rot) {
  const def = MODULES[type];
  return rot % 2 === 0 ? { w: def.w, h: def.h } : { w: def.h, h: def.w };
}
function areaFree(col, row, w, h, ignoreId = null) {
  if (col < 0 || row < 0 || col + w > COLS || row + h > ROWS) return false;
  for (const m of modules) {
    if (m.id === ignoreId) continue;
    const f = m.fp;
    if (col < m.col + f.w && col + w > m.col && row < m.row + f.h && row + h > m.row) return false;
  }
  return true;
}
function defaultModuleData(type) {
  if (MODULES[type].kind !== 'grow') return {};
  return { crop: null, growth: 0, water: 80, nutr: 60, ph: 6.5, health: 100, pests: false, broken: false, readyNotified: false };
}
function makeStatusSprite() {
  const mat = new THREE.SpriteMaterial({ map: statusTex.ready, transparent: true, depthTest: false });
  const s = new THREE.Sprite(mat);
  s.scale.set(0.62, 0.62, 1);
  s.visible = false;
  s.renderOrder = 20;
  return s;
}
function placeModule(type, col, row, rot, data, opts = {}) {
  const def = MODULES[type];
  if (!def) return null;
  const fp = footprint(type, rot);
  if (!opts.force && !areaFree(col, row, fp.w, fp.h)) return null;
  const built = createModuleModel(type);
  if (!built) return null;
  const id = opts.id || state.nextId++;
  const center = moduleCenter(col, row, fp.w, fp.h);
  const group = built.group;
  group.position.set(center.x, 0, center.z);
  group.rotation.y = rot * Math.PI / 2;
  const sprite = makeStatusSprite();
  sprite.position.y = built.height + 0.35;
  group.add(sprite);
  group.traverse(o => { o.userData.moduleId = id; });
  scene.add(group);

  const m = {
    id, type, col, row, rot, fp, group, slots: built.slots,
    data: data ? { ...defaultModuleData(type), ...data } : defaultModuleData(type),
    stageCache: -1, cropCache: null, statusKey: '',
  };
  m.statusSprite = sprite;
  modules.push(m);
  recountLampLights();
  refreshModuleVisual(m, true);

  if (!opts.free && !opts.silent) {
    spend(def.cost);
    sfx.build();
    toast(`${def.icon} <b>${def.name}</b> colocada`);
    markTutorial('placed');
    updateHUD();
  }
  if (!opts.silent) updateGhostAvailability();
  return m;
}
function recountLampLights() {
  let active = 0;
  for (const m of modules) {
    if (m.type !== 'lamp') continue;
    const light = m.group.children.find(o => o.isPointLight);
    if (!light) continue;
    active++;
    light.visible = active <= 4;
  }
}
function removeModule(m, refund = true) {
  const def = MODULES[m.type];
  if (refund) {
    const amount = Math.round(def.cost * 0.6);
    earn(amount);
    toast(`💸 ${def.name} vendida: <b>+$${amount}</b>`);
    sfx.cash();
  }
  if (selectedId === m.id) { selectedId = null; selHighlight.visible = false; }
  scene.remove(m.group);
  disposeGroup(m.group);
  modules = modules.filter(x => x.id !== m.id);
  recountLampLights();
  checkMilestones();
  updateHUD();
}
function disposeGroup(g) {
  g.traverse(o => {
    if (o.isMesh) {
      o.geometry?.dispose();
      const mats = Array.isArray(o.material) ? o.material : [o.material];
      for (const mat of mats) { if (mat) { mat.map?.dispose?.(); mat.dispose(); } }
    }
  });
}
function clearPlants(group) {
  const g = group.userData.plantsG;
  if (!g) return;
  for (const c of [...g.children]) {
    c.traverse(o => {
      if (o.isMesh) {
        o.geometry?.dispose();
        const mats = Array.isArray(o.material) ? o.material : [o.material];
        for (const mat of mats) if (mat) mat.dispose();
      }
    });
    g.remove(c);
  }
}
function refreshModuleVisual(m, force = false) {
  const def = MODULES[m.type];
  if (def.kind !== 'grow') return;
  const d = m.data;
  const stage = !d.crop ? -1 : d.growth < 15 ? 0 : d.growth < 50 ? 1 : 2;
  if (force || stage !== m.stageCache || m.cropCache !== d.crop) {
    m.stageCache = stage; m.cropCache = d.crop;
    clearPlants(m.group);
    const g = m.group.userData.plantsG;
    if (d.crop && g) {
      const cropDef = CROPS[d.crop];
      for (const slot of m.slots) {
        const p = makePlantMesh(cropDef, d.growth);
        p.position.copy(slot);
        p.rotation.y = Math.random() * Math.PI * 2;
        g.add(p);
      }
    }
  }
  // LED bars respond to broken lights
  m.group.traverse(o => {
    if (o.isMesh && o.material && o.material.emissiveIntensity > 1.4) {
      o.material.emissiveIntensity = d.broken ? 0.05 : 2.2;
    }
  });
  // status sprite
  let key = '', tex = null;
  if (d.broken) { key = 'broken'; tex = statusTex.broken; }
  else if (d.pests) { key = 'pest'; tex = statusTex.pest; }
  else if (d.crop && d.growth >= 100) { key = 'ready'; tex = statusTex.ready; }
  else if (d.crop && (d.water < 18 || d.nutr < 12 || d.health < 40)) { key = 'thirst'; tex = statusTex.thirst; }
  if (key !== m.statusKey) {
    m.statusKey = key;
    m.statusSprite.visible = !!tex;
    if (tex) m.statusSprite.material.map = tex;
  }
}

