const sellPrice = (id) => Math.round(state.prices[id] * (state.upgrades.market ? 1.15 : 1));
const contractReward = (c) => Math.round(c.reward * (state.upgrades.contracts ? 1.2 : 1));
function operatingCost() { return state.upgrades.solar ? 22 : 45; }
function ledBonus() { return state.upgrades.led2 ? 1.5 : state.upgrades.led1 ? 1.25 : 1; }
function spend(n) { state.cash -= n; state.dayStats.spent += n; }
function earn(n) { state.cash += n; state.dayStats.earned += n; }
function toast(msg, type = 'info') {
  const box = $('toasts');
  const el = document.createElement('div');
  el.className = 'toast' + (type === 'info' ? '' : ' ' + type);
  el.innerHTML = msg;
  box.appendChild(el);
  while (box.children.length > 3) box.removeChild(box.firstChild);
  setTimeout(() => {
    el.style.transition = 'opacity .3s, transform .3s';
    el.style.opacity = '0'; el.style.transform = 'translateY(-8px)';
    setTimeout(() => el.remove(), 320);
  }, 3800);
}
function checkMilestones() {
  const worth = netWorth(state, modules);
  for (const ms of MILESTONES) {
    if (worth >= ms.worth && !state.milestonesClaimed.includes(ms.name)) {
      state.milestonesClaimed.push(ms.name);
      state.cash += ms.reward;
      state.dayStats.earned += ms.reward;
      $('milestone-name').textContent = ms.name;
      $('milestone-reward').textContent = `Patrimonio $${ms.worth.toLocaleString()} · +$${ms.reward} de bono`;
      $('milestone-toast').classList.remove('hidden');
      sfx.success();
      setTimeout(() => $('milestone-toast').classList.add('hidden'), 5000);
    }
  }
}
function lampBoostFor(m) {
  const cx = m.col + m.fp.w / 2, cz = m.row + m.fp.h / 2;
  for (const l of modules) {
    if (l.type !== 'lamp') continue;
    const lx = l.col + 0.5, lz = l.row + 0.5;
    if (Math.abs(lx - cx) <= 2.2 && Math.abs(lz - cz) <= 2.2) return true;
  }
  return false;
}

