/* ═══════════ CAMERA / TOUCH ═══════════ */
const pointers = new Map();
let drag = null;
let pinch = null;

function panBy(dx, dy) {
  const wpp = (VIEW_H / camZoom) / window.innerHeight;
  const right = tempVec.setFromMatrixColumn(camera.matrixWorld, 0).clone();
  const up = new THREE.Vector3().setFromMatrixColumn(camera.matrixWorld, 1);
  const groundUp = new THREE.Vector3(up.x, 0, up.z);
  if (groundUp.lengthSq() < 0.001) groundUp.set(0, 0, -1);
  groundUp.normalize();
  camTarget.addScaledVector(right, -dx * wpp);
  camTarget.addScaledVector(groundUp, dy * wpp);
  updateCamera();
}
function zoomBy(factor) {
  camZoom = THREE.MathUtils.clamp(camZoom * factor, MIN_ZOOM, MAX_ZOOM);
  updateCamera();
}
function bindTouch() {
  const el = renderer.domElement;
  el.addEventListener('pointerdown', (e) => {
    if (screen !== 'playing') return;
    unlockAudio();
    el.setPointerCapture?.(e.pointerId);
    pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
    if (pointers.size === 1) {
      drag = { startX: e.clientX, startY: e.clientY, lastX: e.clientX, lastY: e.clientY, t: performance.now(), moved: false };
      pinch = null;
    } else if (pointers.size === 2) {
      const [a, b] = [...pointers.values()];
      pinch = { dist: Math.hypot(a.x - b.x, a.y - b.y), zoom: camZoom };
      drag = null;
    }
  });
  el.addEventListener('pointermove', (e) => {
    if (!pointers.has(e.pointerId)) return;
    const prev = pointers.get(e.pointerId);
    pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
    if (pointers.size === 1 && drag) {
      const dx = e.clientX - prev.x, dy = e.clientY - prev.y;
      if (Math.hypot(e.clientX - drag.startX, e.clientY - drag.startY) > 7) drag.moved = true;
      if (drag.moved) panBy(dx, dy);
    } else if (pointers.size === 2 && pinch) {
      const [a, b] = [...pointers.values()];
      const d = Math.hypot(a.x - b.x, a.y - b.y);
      camZoom = THREE.MathUtils.clamp(pinch.zoom * (d / pinch.dist), MIN_ZOOM, MAX_ZOOM);
      updateCamera();
    }
  });
  const endPointer = (e) => {
    if (!pointers.has(e.pointerId)) return;
    const wasTap = pointers.size === 1 && drag && !drag.moved && (performance.now() - drag.t) < 600;
    pointers.delete(e.pointerId);
    if (pointers.size < 2) pinch = null;
    if (pointers.size === 0) {
      if (wasTap) handleTap(e.clientX, e.clientY);
      drag = null;
    }
  };
  el.addEventListener('pointerup', endPointer);
  el.addEventListener('pointercancel', endPointer);
  el.addEventListener('contextmenu', (e) => e.preventDefault());
}
function pickNdc(clientX, clientY, out) {
  const rect = renderer.domElement.getBoundingClientRect();
  out.x = ((clientX - rect.left) / rect.width) * 2 - 1;
  out.y = -((clientY - rect.top) / rect.height) * 2 + 1;
  return out;
}
function handleTap(clientX, clientY) {
  pickNdc(clientX, clientY, pointerNdc);
  raycaster.setFromCamera(pointerNdc, camera);
  if (placing) {
    const hit = raycaster.ray.intersectPlane(floorPlane, tempVec);
    if (hit) {
      const t = worldToTile(tempVec.x, tempVec.z);
      setGhostCell(t.col, t.row);
    }
    return;
  }
  const pickables = [...modules.map(m => m.group), ...world.fixedProps];
  const hits = raycaster.intersectObjects(pickables, true);
  if (hits.length) {
    let o = hits[0].object;
    while (o && o.userData.moduleId === undefined && !o.userData.fixed) o = o.parent;
    if (o && o.userData.moduleId !== undefined) {
      const m = modules.find(mm => mm.id === o.userData.moduleId);
      if (m) { openModuleSheet(m); return; }
    }
    if (o && o.userData.fixed) {
      sfx.blip();
      openSheet(o.userData.fixed === 'market' ? 'market' : 'orders');
      return;
    }
  }
  // tapped open floor / scenery → deselect & close
  selectedId = null;
  selHighlight.visible = false;
  if (activeSheet) closeSheet();
}

