const ghostHighlight = makeFootprintHighlight(0x4ade80);
ghostHighlight.visible = false;
scene && scene.add(ghostHighlight);

function startPlacing(type) {
  const def = MODULES[type];
  if (!def) return;
  if (state.cash < def.cost) { toast('No tienes dinero suficiente. Vende algo primero 🏪', 'bad'); sfx.error(); return; }
  exitPlacing();
  closeSheet();
  const built = createModuleModel(type);
  const ghost = built.group;
  ghost.visible = false;
  ghost.traverse(o => {
    if (o.isMesh) { o.material = ghostMat; o.castShadow = false; o.receiveShadow = false; }
    if (o.isPointLight) o.visible = false;
  });
  scene.add(ghost);
  placing = { type, rot: 0, ghost, col: null, row: null, valid: false };
  selHighlight.visible = false;
  ghostHighlight.visible = false;
  world.grid.visible = true;
  $('placement-bar').classList.remove('hidden');
  $('pb-icon').textContent = def.icon;
  $('pb-name').textContent = def.name;
  $('pb-hint').textContent = `$${def.cost} · toca una celda`;
  $('pb-confirm').disabled = true;
  updatePlacementBar();
}
function updatePlacementBar() {
  if (!placing) return;
  const def = MODULES[placing.type];
  const confirm = $('pb-confirm');
  confirm.disabled = !(placing.valid && state.cash >= def.cost);
  if (placing.col === null) {
    $('pb-hint').textContent = `$${def.cost} · toca una celda del suelo`;
  } else if (!placing.valid) {
    $('pb-hint').textContent = '❌ Ese espacio está ocupado';
  } else if (state.cash < def.cost) {
    $('pb-hint').textContent = '❌ Falta dinero';
  } else {
    $('pb-hint').textContent = `$${def.cost} · confirma con ✓`;
  }
}
function setGhostCell(col, row) {
  if (!placing) return;
  const def = MODULES[placing.type];
  const fp = footprint(placing.type, placing.rot);
  placing.col = col; placing.row = row;
  placing.valid = areaFree(col, row, fp.w, fp.h) && state.cash >= def.cost;
  const c = moduleCenter(col, row, fp.w, fp.h);
  placing.ghost.position.set(c.x, 0, c.z);
  placing.ghost.rotation.y = placing.rot * Math.PI / 2;
  placing.ghost.visible = true;
  ghostHighlight.position.set(c.x, 0, c.z);
  ghostHighlight.scale.set(fp.w * TILE - 0.06, 1, fp.h * TILE - 0.06);
  ghostHighlight.visible = true;
  const color = placing.valid ? 0x4ade80 : 0xf87171;
  ghostHighlight.userData.plane.material.color.setHex(color);
  ghostHighlight.userData.border.material.color.setHex(color);
  ghostMat.color.setHex(placing.valid ? 0x4ade80 : 0xf87171);
  updatePlacementBar();
  sfx.blip();
}
function rotateGhost() {
  if (!placing) return;
  placing.rot = (placing.rot + 1) % 2;
  if (placing.col !== null) setGhostCell(placing.col, placing.row);
  else sfx.click();
}
function confirmPlacement() {
  if (!placing || !placing.valid) return;
  const def = MODULES[placing.type];
  if (state.cash < def.cost) { toast('Falta dinero', 'bad'); sfx.error(); return; }
  placeModule(placing.type, placing.col, placing.row, placing.rot, null, {});
  placing.ghost.visible = false;
  ghostHighlight.visible = false;
  placing.col = null; placing.row = null; placing.valid = false;
  ghostMat.color.setHex(0x4ade80);
  updatePlacementBar();
  $('pb-hint').textContent = 'Toca otra celda o cancela';
  if (state.cash < def.cost) { exitPlacing(); toast('Te quedaste sin dinero para más módulos', 'warn'); }
}
function exitPlacing() {
  if (!placing) return;
  scene.remove(placing.ghost);
  disposeGhost(placing.ghost);
  placing = null;
  ghostHighlight.visible = false;
  world.grid.visible = false;
  $('placement-bar').classList.add('hidden');
}
function disposeGhost(g) {
  g.traverse(o => { if (o.isMesh) { o.geometry?.dispose(); } });
}

