  let content = '';
  if (m.type === 'tank') {
    content = `<div class="empty-state"><span class="es-icon">💧</span>Depósito de reserva conectado a la granja.<br>Puedes regar todos los módulos de golpe.</div>
      <button class="big-btn primary" data-action="refill">💧 REGAR TODOS LOS RACKS</button>`;
  } else if (m.type === 'bench') {
    content = `<div class="empty-state"><span class="es-icon">🧪</span>Banco para mezclar sales nutritivas.<br>Reservas: <b>${state.nutrient}</b> unidades.</div>
      <button class="big-btn primary" data-action="mix">🧪 PREPARAR +2 NUTRIENTES · $25</button>`;
  } else if (m.type === 'lamp') {
    content = `<div class="empty-state"><span class="es-icon">💡</span>Lámpara LED de espectro completo.<br>Da <b>+10% de crecimiento</b> a los racks en un radio de 2 casillas.</div>`;
  } else {
    content = `<div class="empty-state"><span class="es-icon">${def.icon}</span>${def.desc}<br>Decora tu invernadero a tu gusto.</div>`;
  }
  return `${content}
    <div class="mini-actions">
      ${def.w !== def.h ? `<button data-action="rotate">↻ Rotar</button>` : ''}
      ${sellArmed === m.id
        ? `<button data-action="sell-confirm" class="danger">Confirmar +$${Math.round(def.cost * 0.6)}</button>`
        : `<button data-action="sell" class="danger">Vender +$${Math.round(def.cost * 0.6)}</button>`}
    </div>`;
}

/* ── market ── */
function marketSheetHTML() {
  const rows = CROP_IDS.filter(id => state.produce[id] > 0);
  const total = rows.reduce((s, id) => s + state.produce[id] * sellPrice(id), 0);
  if (!rows.length) {
    return `<div class="empty-state"><span class="es-icon">🧺</span>Tu almacén está vacío.<br>Cosecha módulos listos (✅) y vuelve a vender.</div>
      <div class="daytip">Los precios cambian cada día. Vender con ▲ azul te da más dinero que la media.</div>`;
  }
  return `<div class="section-title"><span>Tu cosecha</span><span>Total $${total}</span></div>
    ${rows.map(id => {
      const q = state.produce[id], p = sellPrice(id), up = state.prices[id] >= CROPS[id].sell;
      return `<div class="sell-row">
        <div class="sr-icon">${CROPS[id].icon}</div>
        <div class="sr-main"><div class="sr-name">${CROPS[id].name} ×${q}</div>
          <div class="sr-price">$${p} c/u <span class="${up ? 'up' : 'down'}">${up ? '▲' : '▼'}</span></div></div>
        <button class="sell-btn" data-action="market-sell" data-crop="${id}">VENDER<small>$${q * p}</small></button>
      </div>`;
    }).join('')}
    <button class="big-btn primary" data-action="market-sell-all" style="margin-top:6px">💰 VENDER TODO · $${total}</button>`;
}

/* ── orders ── */
function ordersSheetHTML() {
  const act = state.activeContracts.length
    ? state.activeContracts.map(c => {
      const have = state.produce[c.crop], ok = have >= c.qty;
      const left = c.deadline - state.day;
      return `<div class="order-card">
        <div class="oc-client">🍽️ ${c.client}</div>
        <div class="oc-detail">${CROPS[c.crop].icon} <b>${c.qty}× ${CROPS[c.crop].name}</b> · pago <b>$${contractReward(c).toLocaleString()}</b></div>
        <div class="oc-deadline">${left <= 0 ? '⚠️ vence HOY' : `vence Día ${c.deadline} (${left}d)`} · tienes ${have}/${c.qty}</div>
        <div class="oc-actions"><button class="oc-btn" data-action="deliver" data-id="${c.id}" ${ok ? '' : 'disabled'}>🚚 ENTREGAR</button></div>
      </div>`;
    }).join('')
    : `<div class="empty-state"><span class="es-icon">📭</span>Sin pedidos activos.<br>Acepta ofertas de restaurantes abajo.</div>`;
  const offers = state.offers.length
    ? state.offers.map(c => `<div class="order-card">
        <div class="oc-client">📨 ${c.client}</div>
        <div class="oc-detail">${CROPS[c.crop].icon} <b>${c.qty}× ${CROPS[c.crop].name}</b> · pago <b>$${contractReward(c).toLocaleString()}</b></div>
        <div class="oc-deadline">Entrega antes del Día ${c.deadline}</div>
        <div class="oc-actions"><button class="oc-btn" data-action="accept" data-id="${c.id}" ${state.activeContracts.length >= 4 ? 'disabled' : ''}>✍️ ACEPTAR</button></div>
      </div>`).join('')
    : `<div class="empty-state">No hay ofertas hoy. Vuelve mañana 🌙</div>`;
  return `<div class="section-title"><span>Activos (${state.activeContracts.length}/4)</span></div>${act}
    <div class="section-title"><span>Nuevas ofertas</span><span>se renuevan cada día</span></div>${offers}`;
}

/* ── shop ── */
function shopSheetHTML() {
  const seeds = CROP_IDS.map(id => {
    const c = CROPS[id];
    return `<div class="shop-row">
      <div class="sh-icon">${c.icon}</div>
      <div class="sh-main"><div class="sh-name">Semilla de ${c.name}</div>
        <div class="sh-desc">tienes ${state.seeds[id]} · crece en ${c.growTime}s · vende ~$${c.sell}</div></div>
      <button class="sh-btn" data-action="buy-seed" data-crop="${id}" data-qty="1" ${state.cash < c.seedCost ? 'disabled' : ''}>$${c.seedCost}</button>
      <button class="sh-btn" data-action="buy-seed" data-crop="${id}" data-qty="5" ${state.cash < c.seedCost * 5 ? 'disabled' : ''}>×5</button>
    </div>`;
  }).join('');
  const supplies = `
    <div class="shop-row"><div class="sh-icon">🧴</div>
      <div class="sh-main"><div class="sh-name">Pesticida · ${state.pesticide}</div><div class="sh-desc">cura las plagas de un módulo</div></div>
      <button class="sh-btn" data-action="buy-pesticide" ${state.cash < 18 ? 'disabled' : ''}>$18</button></div>
    <div class="shop-row"><div class="sh-icon">🧪</div>
      <div class="sh-main"><div class="sh-name">Nutrientes · ${state.nutrient}</div><div class="sh-desc">+2 unidades de solución</div></div>
      <button class="sh-btn" data-action="buy-nutrient" ${state.cash < 25 ? 'disabled' : ''}>$25</button></div>`;
  const upgrades = UPGRADES.map(u => {
    const owned = state.upgrades[u.id];
    const locked = u.needs && !state.upgrades[u.needs];
    return `<div class="shop-row"><div class="sh-icon">${u.icon}</div>
      <div class="sh-main"><div class="sh-name">${u.name}</div><div class="sh-desc">${u.desc}</div></div>
      ${owned ? `<button class="sh-btn owned" disabled>✓</button>`
        : `<button class="sh-btn" data-action="buy-upgrade" data-id="${u.id}" ${locked || state.cash < u.cost ? 'disabled' : ''}>$${u.cost.toLocaleString()}</button>`}
    </div>`;
  }).join('');
  return `<div class="section-title"><span>Semillas</span><span>efectivo $${Math.floor(state.cash)}</span></div>${seeds}
    <div class="section-title"><span>Consumibles</span></div>${supplies}
    <div class="section-title"><span>Mejoras</span></div>${upgrades}`;
}

/* ── day ── */
function daySheetHTML() {
