/* ═══════════ SHEET ACTIONS ═══════════ */
function bindUI() {
  $('btn-new').addEventListener('click', () => { sfx.success(); newGame(true); });
  $('btn-continue').addEventListener('click', () => {
    if (loadGame()) { sfx.success(); startPlaying(); toast('💾 Partida cargada'); }
    else toast('No se encontró partida', 'bad');
  });
  $('btn-help-title').addEventListener('click', () => openHelp('title'));
  $('btn-help-close').addEventListener('click', () => closeHelp());
  $('btn-next-day').addEventListener('click', () => nextDay());
  $('btn-fullscreen').addEventListener('click', toggleFullscreen);
  $('btn-menu').addEventListener('click', () => openSheet('menu'));
  $('sheet-close').addEventListener('click', () => closeSheet());
  $('sheet-scrim').addEventListener('click', () => closeSheet());
  $('zoom-in').addEventListener('click', () => { sfx.blip(); zoomBy(1.2); });
  $('zoom-out').addEventListener('click', () => { sfx.blip(); zoomBy(1 / 1.2); });
  $('pb-rotate').addEventListener('click', rotateGhost);
  $('pb-confirm').addEventListener('click', confirmPlacement);
  $('pb-cancel').addEventListener('click', exitPlacing);
  $('tut-collapse').addEventListener('click', () => {
    state.tutorial.collapsed = !state.tutorial.collapsed;
    updateTutorialUI();
  });
  $('bottom-nav').addEventListener('click', (e) => {
    const b = e.target.closest('button[data-nav]');
    if (!b) return;
    sfx.click();
    openSheet(b.dataset.nav);
  });
  $('sheet-body').addEventListener('click', (e) => {
    const btn = e.target.closest('[data-action]');
    if (!btn) return;
    handleSheetAction(btn.dataset.action, btn);
  });
}
function handleSheetAction(action, btn) {
  const m = modules.find(mm => mm.id === selectedId);
  if (action === 'select-build') { sfx.click(); startPlacing(btn.dataset.type); return; }
  if (action === 'plant') { if (m) plantCrop(m, btn.dataset.crop); return; }
  if (action === 'water') { if (m) waterModule(m); return; }
  if (action === 'feed') { if (m) feedModule(m); return; }
  if (action === 'ph') { if (m) phModule(m); return; }
  if (action === 'spray') { if (m) sprayModule(m); return; }
  if (action === 'harvest') { if (m) harvestModule(m); return; }
  if (action === 'repair') { if (m) repairModule(m); return; }
  if (action === 'rotate') { if (m) rotateModule(m); return; }
  if (action === 'sell') { sellArmed = m ? m.id : null; sfx.click(); renderSheet(); return; }
  if (action === 'sell-confirm') {
    if (m) { removeModule(m, true); closeSheet(); }
    sellArmed = null; return;
  }
  if (action === 'refill') { refillAll(); return; }
  if (action === 'mix') { mixNutrients(); return; }
  if (action === 'market-sell') { sellCrop(btn.dataset.crop); return; }
  if (action === 'market-sell-all') { sellAll(); return; }
  if (action === 'accept') { acceptOffer(btn.dataset.id); return; }
  if (action === 'deliver') { deliverContract(btn.dataset.id); return; }
  if (action === 'buy-seed') { buySeed(btn.dataset.crop, +btn.dataset.qty); return; }
  if (action === 'buy-pesticide') { buySupply('pesticide'); return; }
  if (action === 'buy-nutrient') { buySupply('nutrient'); return; }
  if (action === 'buy-upgrade') { buyUpgrade(btn.dataset.id); return; }
  if (action === 'endday') { showSleep(); return; }
  if (action === 'save') { saveGame(true); return; }
  if (action === 'help') { openHelp('playing'); return; }
  if (action === 'fullscreen') { toggleFullscreen(); return; }
  if (action === 'mute') { setMuted(!isMuted()); renderSheet(); return; }
  if (action === 'quittitle') { saveGame(false); quitToTitle(); return; }
}

/* ═══════════ MODULE ACTIONS ═══════════ */
function plantCrop(m, cropId) {
  const d = m.data;
  if (d.crop) { toast('Ya hay un cultivo aquí', 'warn'); return; }
  if (state.seeds[cropId] <= 0) { toast(`No tienes semillas de ${CROPS[cropId].name}. Compra en la tienda 🛒`, 'bad'); sfx.error(); return; }
  state.seeds[cropId]--;
  Object.assign(d, {
    crop: cropId, growth: 3, water: Math.max(d.water, 75), nutr: Math.max(d.nutr, 55),
    health: 100, pests: false, ph: 6.5, readyNotified: false,
  });
  refreshModuleVisual(m, true);
  sfx.plant();
  toast(`🌱 ${CROPS[cropId].name} plantada`);
  markTutorial('planted');
  renderSheet(); updateHUD();
}
function waterModule(m) {
  if (m.data.water >= 99) { toast('El agua ya está llena 💧'); return; }
  m.data.water = 100;
  sfx.water();
  renderSheet(); updateHUD();
}
function feedModule(m) {
  if (!m.data.crop) { toast('Primero planta un cultivo', 'warn'); return; }
  if (state.nutrient <= 0) { toast('Sin nutrientes: mézclalos en el banco o compra en la tienda', 'warn'); sfx.error(); return; }
  state.nutrient--;
  m.data.nutr = Math.min(100, m.data.nutr + 45);
  sfx.dose();
  renderSheet(); updateHUD();
}
function phModule(m) {
  if (state.cash < 4) { toast('El buffer de pH cuesta $4', 'bad'); sfx.error(); return; }
  spend(4);
  m.data.ph = 6.5;
  sfx.click();
  toast('⚗️ pH ajustado a 6.50');
  renderSheet(); updateHUD();
}
function sprayModule(m) {
  if (!m.data.pests) { toast('No hay plagas aquí 🌿'); return; }
  if (state.pesticide <= 0) { toast('Sin pesticida: compra en la tienda', 'bad'); sfx.error(); return; }
  state.pesticide--;
  m.data.pests = false;
  refreshModuleVisual(m, true);
  sfx.spray();
  toast('🧴 Plagas eliminadas');
  renderSheet(); updateHUD();
}
function harvestModule(m) {
  const d = m.data;
  if (!d.crop || d.growth < 100) return;
  const cropDef = CROPS[d.crop], def = MODULES[m.type];
  state.produce[d.crop] += def.yield;
  state.dayStats.harvested += def.yield;
  d.crop = null; d.growth = 0; d.pests = false; d.readyNotified = false; d.health = 100;
  refreshModuleVisual(m, true);
  sfx.harvest();
  toast(`🌾 Cosechaste <b>${def.yield}× ${cropDef.name}</b> · véndelas en el mercado`);
  renderSheet(); updateHUD();
}
function repairModule(m) {
  if (state.cash < 15) { toast('Necesitas $15 para reparar', 'bad'); sfx.error(); return; }
  spend(15);
  m.data.broken = false;
  refreshModuleVisual(m, true);
  sfx.build();
  toast('🔧 Lámpara reparada');
  renderSheet(); updateHUD();
}
function rotateModule(m) {
  const newRot = (m.rot + 1) % 2;
  const fp = footprint(m.type, newRot);
  if (!areaFree(m.col, m.row, fp.w, fp.h, m.id)) { toast('No hay espacio para rotar aquí', 'bad'); sfx.error(); return; }
  m.rot = newRot; m.fp = fp;
  const c = moduleCenter(m.col, m.row, fp.w, fp.h);
  m.group.position.set(c.x, 0, c.z);
  m.group.rotation.y = newRot * Math.PI / 2;
  selectModule(m);
  sfx.click();
  renderSheet();
}
function refillAll() {
  let count = 0;
  for (const mod of modules) {
    if (MODULES[mod.type].kind === 'grow' && mod.data.water < 99) { mod.data.water = 100; count++; }
  }
  sfx.water();
  toast(count ? `💧 Regaste ${count} módulo${count === 1 ? '' : 's'}` : 'Todo estaba ya regado 💧');
  renderSheet(); updateHUD();
}
function mixNutrients() {
  if (state.cash < 25) { toast('Preparar nutrientes cuesta $25', 'bad'); sfx.error(); return; }
  spend(25);
  state.nutrient += 2;
  sfx.dose();
  toast('🧪 +2 nutrientes preparados');
  renderSheet(); updateHUD();
}

/* ═══════════ MARKET / CONTRACTS / SHOP ═══════════ */
function sellCrop(id) {
  const q = state.produce[id];
  if (!q) return;
  const amount = q * sellPrice(id);
  state.produce[id] = 0;
  earn(amount);
  sfx.cash();
  toast(`🏪 Vendiste ${CROPS[id].name}: <b>+$${amount.toLocaleString()}</b>`);
  markTutorial('sold');
  checkMilestones();
  renderSheet(); updateHUD();
}
function sellAll() {
  let total = 0;
  for (const id of CROP_IDS) { total += state.produce[id] * sellPrice(id); state.produce[id] = 0; }
  if (total <= 0) { toast('No hay nada para vender', 'warn'); sfx.error(); return; }
  earn(total);
  sfx.cash();
  toast(`🏪 Vendiste toda la cosecha: <b>+$${total.toLocaleString()}</b>`);
  markTutorial('sold');
  checkMilestones();
  renderSheet(); updateHUD();
}
function acceptOffer(id) {
  const i = state.offers.findIndex(o => o.id === id);
  if (i < 0 || state.activeContracts.length >= 4) return;
  state.activeContracts.push(state.offers.splice(i, 1)[0]);
  sfx.click();
  toast('✍️ Pedido aceptado');
  renderSheet(); updateHUD();
}
function deliverContract(id) {
  const i = state.activeContracts.findIndex(c => c.id === id);
  if (i < 0) return;
  const c = state.activeContracts[i];
  if (state.produce[c.crop] < c.qty) { toast('No tienes suficiente producción', 'bad'); sfx.error(); return; }
  state.produce[c.crop] -= c.qty;
  const reward = contractReward(c);
  earn(reward);
  state.activeContracts.splice(i, 1);
  sfx.cash();
  toast(`🚚 Entregado a <b>${c.client}</b>: +$${reward.toLocaleString()}`);
  markTutorial('sold');
  checkMilestones();
  renderSheet(); updateHUD();
}
function buySeed(cropId, qty) {
  const cost = CROPS[cropId].seedCost * qty;
  if (state.cash < cost) { toast('Falta dinero', 'bad'); sfx.error(); return; }
  spend(cost);
  state.seeds[cropId] += qty;
  sfx.click();
  renderSheet(); updateHUD();
}
function buySupply(kind) {
  if (kind === 'pesticide') {
    if (state.cash < 18) return sfx.error();
    spend(18); state.pesticide++;
  } else {
    if (state.cash < 25) return sfx.error();
    spend(25); state.nutrient += 2;
  }
  sfx.click();
  renderSheet(); updateHUD();
}
function buyUpgrade(id) {
  const u = UPGRADES.find(x => x.id === id);
  if (!u || state.upgrades[id] || state.cash < u.cost) return sfx.error();
  if (u.needs && !state.upgrades[u.needs]) return sfx.error();
  spend(u.cost);
  state.upgrades[id] = true;
  if (id === 'led2') state.upgrades.led1 = true;
  sfx.build();
  toast(`${u.icon} <b>${u.name}</b> instalada`);
  checkMilestones();
  renderSheet(); updateHUD();
}

/* ═══════════ GAME FLOW ═══════════ */
function newGame(lock) {
  state = defaultState();
  clearAllModules();
  selectedId = null;
  closeSheet(); exitPlacing();
  selHighlight.visible = false;
  camTarget.set(-1.2, 0, 0.6); camZoom = defaultZoom(); updateCamera();
  // starter layout
  placeModule('growrack', 3, 3, 0, null, { free: true, silent: true });
  placeModule('growrack', 3, 5, 0, null, { free: true, silent: true });
  placeModule('tank', 6, 2, 0, null, { free: true, silent: true });
  placeModule('bench', 6, 4, 0, null, { free: true, silent: true });
  placeModule('planter', 8, 3, 0, null, { free: true, silent: true });
  placeModule('crate', 8, 5, 0, null, { free: true, silent: true });
  placeModule('sign', 1, 2, 0, null, { free: true, silent: true });
  updateHUD();
  startPlaying();
  toast('🌱 ¡Bienvenido a Verdia Farms! Toca <b>CONSTRUIR</b> para ampliar tu granja.', 'info');
  setTimeout(() => { if (screen === 'playing') toast('👆 Arrastra con un dedo para moverte y pellizca para zoom.'); }, 2800);
  setTimeout(() => { if (screen === 'playing') toast('💧 Toca un rack para plantar y cuidar tus cultivos.'); }, 5600);
}
function defaultZoom() {
  const a = window.innerWidth / window.innerHeight;
  return a < 0.8 ? 1.0 : 0.88;
}
function startPlaying() {
  screen = 'playing';
  $('title-screen').classList.add('hidden');
  $('sleep-screen').classList.add('hidden');
  $('help-modal').classList.add('hidden');
  $('topbar').classList.remove('hidden');
  $('bottom-nav').classList.remove('hidden');
  updateHUD();
  updateTutorialUI();
  camZoom = defaultZoom();
  updateCamera();
}
function renderTitle() {
  screen = 'title';
  $('topbar').classList.add('hidden');
  $('bottom-nav').classList.add('hidden');
  $('tutorial').classList.add('hidden');
  $('sheet').classList.add('hidden');
  $('sheet-scrim').classList.add('hidden');
  $('placement-bar').classList.add('hidden');
  $('title-screen').classList.remove('hidden');
  $('btn-continue').style.visibility = localStorage.getItem(SAVE_KEY) ? 'visible' : 'hidden';
  closeSheet(); exitPlacing();
  camZoom = 0.72; updateCamera();
}
function quitToTitle() {
  closeSheet(); exitPlacing();
  renderTitle();
}
function showSleep() {
  if (screen === 'sleep') return;
  screen = 'sleep';
  closeSheet(); exitPlacing();
  selHighlight.visible = false;
  sfx.sleep();
  $('sleep-title').textContent = `🌙 Día ${state.day} completado`;
  $('sleep-summary').innerHTML = `
