  const growMods = modules.filter(m => MODULES[m.type].kind === 'grow' && m.data.crop && !m.data.pests);
  if (growMods.length && Math.random() < 0.42) {
    const m = growMods[Math.floor(Math.random() * growMods.length)];
    m.data.pests = true;
    refreshModuleVisual(m, false);
    setTimeout(() => toast(`🐛 ¡Plagas en un ${MODULES[m.type].name}! Tócalo y fumiga.`, 'warn'), 900);
  }
  const lightMods = modules.filter(m => MODULES[m.type].kind === 'grow' && !m.data.broken);
  if (lightMods.length && Math.random() < 0.16) {
    const m = lightMods[Math.floor(Math.random() * lightMods.length)];
    m.data.broken = true;
    refreshModuleVisual(m, true);
    setTimeout(() => toast(`⚡ Lámpara averiada en un ${MODULES[m.type].name}. Repárala por $15.`, 'warn'), 1700);
  }
  $('sleep-screen').classList.add('hidden');
