/* ═══════════ SIMULATION ═══════════ */
function update(dt) {
  if (screen !== 'playing') return;
  state.timeMin += dt * TIME_SCALE;
  if (state.timeMin >= DAY_END) { state.timeMin = DAY_END; showSleep(); return; }

  const t = (state.timeMin - DAY_START) / (DAY_END - DAY_START);
  world.updateDaylight(t);
  $('scene-tint').style.background = t < 0.1
    ? `rgba(255, 170, 90, ${0.14 * (1 - t / 0.1)})`
    : t > 0.88 ? `rgba(255, 120, 70, ${0.16 * ((t - 0.88) / 0.12)})` : 'transparent';

  for (const m of modules) {
    const def = MODULES[m.type];
    if (def.kind !== 'grow') continue;
    const d = m.data;
    if (!d.crop) continue;
    // drains
    const waterDrain = state.upgrades.autoWater ? 0.28 : 0.95;
    d.water = Math.max(0, d.water - waterDrain * dt);
    d.nutr = Math.max(0, d.nutr - 0.6 * dt);
    if (state.upgrades.autoWater && d.water < 55) d.water = Math.min(100, d.water + 24 * dt);
    if (state.upgrades.autoDose && d.nutr < 60) d.nutr = Math.min(60, d.nutr + 7 * dt);
    d.ph += (Math.random() - 0.48) * 0.11 * dt;
    d.ph = THREE.MathUtils.clamp(d.ph, 5.3, 7.7);
    const phOk = d.ph >= 5.9 && d.ph <= 7.0;
    let stressed = false;
    if (d.water <= 0) { d.health -= 2.4 * dt; stressed = true; }
    if (d.nutr <= 0) { d.health -= 1.4 * dt; stressed = true; }
    if (!phOk) d.health -= 1.0 * dt;
    if (d.pests) { d.health -= 2.0 * dt; stressed = true; }
    if (!stressed && phOk) d.health = Math.min(100, d.health + 1.8 * dt);
    if (d.health <= 0) {
      toast(`💀 Tu ${CROPS[d.crop].name} murió por descuido`, 'bad');
      d.crop = null; d.growth = 0; d.health = 100; d.pests = false; d.readyNotified = false;
      refreshModuleVisual(m, true);
      sfx.error();
      continue;
    }
    if (!d.broken && d.growth < 100) {
      const cropDef = CROPS[d.crop];
      const rate = (100 / cropDef.growTime) * def.growth * ledBonus() * (lampBoostFor(m) ? 1.1 : 1)
        * Math.max(0.3, d.health / 100) * (phOk ? 1 : 0.4);
      d.growth = Math.min(100, d.growth + rate * dt);
      if (d.growth >= 100 && !d.readyNotified) {
        d.readyNotified = true;
        toast(`✅ ${def.icon} ${def.name}: ¡${CROPS[d.crop].name} lista para cosechar!`);
        sfx.blip();
      }
    }
    refreshModuleVisual(m);
  }

  // status sprite bob
  const bob = Math.sin(clock.elapsedTime * 3) * 0.06;
  for (const m of modules) {
    if (m.statusSprite && m.statusSprite.visible) {
      m.statusSprite.position.y = (m.group.userData.height || 2) + 0.4 + bob;
    }
  }
  // selection pulse
  if (selHighlight.visible) {
    selHighlight.userData.border.material.opacity = 0.6 + Math.sin(clock.elapsedTime * 4) * 0.3;
  }

  hudTimer += dt;
  if (hudTimer > 0.3) { hudTimer = 0; updateHUD(); if (activeSheet === 'rack' || activeSheet === 'utility') liveUpdateSheet(); }
}

let liveKey = '';
function liveUpdateSheet() {
