body.is-placing #zoom-controls { display: none !important; }
.bc-placed {
  margin-top: 4px; font-size: 8px; font-weight: 800; color: #15803d;
  background: #e7f7e9; border-radius: 5px; padding: 2px 4px; align-self: flex-start;
}

/* comparación de sistemas */
.scenario-list { display: flex; flex-direction: column; gap: 9px; }
.scenario-card {
  background: #fffef8; border: 1.5px solid var(--line); border-radius: 14px;
  padding: 10px 11px; box-shadow: 0 2px 0 rgba(18, 60, 44, 0.06);
}
.scenario-card.active { border-color: #22c55e; background: #f4fbf2; box-shadow: 0 0 0 2px rgba(34,197,94,0.14); }
.sc-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 8px; }
.sc-title-wrap { min-width: 0; }
.sc-name { font-family: 'Baloo 2'; font-weight: 800; font-size: 15px; line-height: 1.15; color: var(--green-dark); }
.sc-counts { font-size: 9.5px; color: var(--ink-soft); line-height: 1.3; margin-top: 1px; }
.sc-badge {
  font-family: 'Baloo 2'; font-weight: 800; font-size: 8px; letter-spacing: 1px;
  background: #dcfce7; color: #15803d; border: 1px solid #86efac; border-radius: 999px;
  padding: 2px 7px; flex-shrink: 0;
}
.sc-metrics { display: grid; grid-template-columns: repeat(3, 1fr); gap: 5px 8px; margin-top: 8px; }
.sc-metrics small { display: block; font-size: 7.5px; letter-spacing: 0.5px; text-transform: uppercase; color: var(--ink-soft); font-weight: 800; }
.sc-metrics b { font-family: 'Baloo 2'; font-size: 12.5px; color: var(--ink); line-height: 1.2; }
.sc-metrics b.neg { color: #b91c1c; }
.sc-actions { display: flex; gap: 6px; margin-top: 9px; }
.sc-actions .mini-btn { flex: 1; font-size: 9.5px; min-height: 32px; padding: 4px 6px; }
.sc-actions .mini-btn[disabled] { opacity: 0.55; }

/* proyección de escala */
.scale-hero {
  background: linear-gradient(135deg, #0d3b2e, #14532d 65%, #166534);
  color: #ecfdf5; border: 1.5px solid #34d399; border-radius: 16px;
  padding: 11px 13px; margin: 6px 0 4px;
}
.scale-head { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.sh-label { font-size: 8px; letter-spacing: 1.2px; color: #86efac; font-weight: 800; }
.sh-title { font-family: 'Baloo 2'; font-weight: 800; font-size: 22px; line-height: 1.05; color: var(--gold); }
.scale-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 7px 10px; margin-top: 10px; }
.scale-grid small { display: block; font-size: 7.5px; letter-spacing: 0.7px; color: #86efac; font-weight: 800; }
.scale-grid b { font-family: 'Baloo 2'; font-size: 14px; color: #ecfccb; line-height: 1.2; }
.scale-note { font-size: 9px; color: #b8efcd; line-height: 1.35; margin-top: 8px; opacity: 0.9; }
.stepper.light { background: rgba(255,255,255,0.12); border-color: rgba(134,239,172,0.4); }
.stepper.light button { background: rgba(255,255,255,0.14); color: #ecfccb; }
.stepper.light .sv { color: #fef3c7; }

/* rendimiento marginal */
.delta-list { display: flex; flex-direction: column; gap: 8px; }
.delta-card {
  background: #fffef8; border: 1.5px solid var(--line); border-radius: 13px; padding: 9px 10px;
}
.dc-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 8px; }
.dc-name { font-family: 'Baloo 2'; font-weight: 800; font-size: 12.5px; line-height: 1.2; color: var(--ink); }
.dc-sub { font-size: 9px; color: var(--ink-soft); line-height: 1.3; margin-top: 1px; }
.dc-money { font-family: 'Baloo 2'; font-weight: 800; font-size: 15px; color: var(--gold-deep); white-space: nowrap; text-align: right; }
.dc-money small { display: block; font-family: 'Nunito'; font-size: 7.5px; color: var(--ink-soft); font-weight: 700; }
.dc-row { display: flex; justify-content: space-between; gap: 10px; border-top: 1px dashed #e7efe2; padding: 4px 0 0; margin-top: 4px; font-size: 10.5px; color: var(--ink-soft); }
.dc-row b { font-family: 'Baloo 2'; font-size: 11.5px; color: var(--ink); text-align: right; }

/* economía */
.econ-box { background: #fffef8; border: 1.5px solid var(--line); border-radius: 12px; padding: 4px 10px; }
.warning-box ul { margin: 4px 0 0 14px; padding: 0; }
.warning-box li { margin: 2px 0; }
.warning-box + .disclaimer { margin-top: 8px; }

